        ["cal.lead"] = new() { ["en"] = "On a call other people can hear, the other side is told first, in a language their number suggests they speak. Nothing listens until it has gone out.", ["es"] = "En una llamada que otros pueden oír, se avisa primero a la otra parte, en el idioma que sugiere su número. Nada escucha hasta que se haya reproducido.", ["fr"] = "Sur un appel que d'autres peuvent entendre, l'autre partie est prévenue d'abord, dans la langue que son numéro suggère. Rien n'écoute avant qu'il soit passé.", ["de"] = "Bei einem Gespräch, das andere mithören können, wird die Gegenseite zuerst informiert, in der Sprache, die ihre Nummer nahelegt. Nichts hört zu, bevor er gelaufen ist.", ["pt"] = "Numa chamada que outros podem ouvir, a outra parte é avisada primeiro, no idioma que o número sugere. Nada escuta até ter sido reproduzido.", ["it"] = "In una chiamata che altri possono sentire, l'altra parte viene avvisata per prima, nella lingua che il numero suggerisce. Nulla ascolta finché non è stato riprodotto.", ["ja"] = "他の人にも聞こえる通話では、相手の番号から推測される言語で、まず相手に伝えます。流れるまでは何も聞き取りません。", ["zh"] = "在他人也能听到的通话中，先用其号码所提示的语言告知对方。在播放之前，不会开始收听。", ["hi"] = "जिस कॉल को दूसरे भी सुन सकते हैं, वहाँ पहले दूसरे पक्ष को उनके नंबर से अनुमानित भाषा में बताया जाता है। जब तक वह न चल जाए, कुछ भी नहीं सुना जाता।", ["ar"] = "في مكالمة يمكن لآخرين سماعها، يُبلَّغ الطرف الآخر أولًا بلغة يرجّحها رقمه. ولا يستمع شيء قبل أن يُذاع." },
