        ["bes.pitch"] = new() { ["en"] = "Paste what you are working on — a page for a customer, a strategy note. It is read here on this device, remarked on, and dropped: nothing is saved and nothing is edited.", ["es"] = "Pega lo que estés escribiendo — una página para un cliente, una nota de estrategia. Se lee aquí, en este dispositivo, se comenta y se descarta: no se guarda nada ni se edita nada.", ["fr"] = "Collez ce sur quoi vous travaillez — une page pour un client, une note de stratégie. C'est lu ici, sur cet appareil, commenté, puis abandonné : rien n'est enregistré et rien n'est modifié.", ["de"] = "Füge ein, woran du arbeitest — eine Seite für einen Kunden, eine Strategienotiz. Es wird hier auf diesem Gerät gelesen, kommentiert und verworfen: nichts wird gespeichert und nichts verändert.", ["pt"] = "Cole aquilo em que está a trabalhar — uma página para um cliente, uma nota de estratégia. É lido aqui, neste dispositivo, comentado e descartado: nada é guardado e nada é alterado.", ["it"] = "Incolla ciò a cui stai lavorando — una pagina per un cliente, una nota di strategia. Viene letto qui, su questo dispositivo, commentato e scartato: non si salva nulla e non si modifica nulla.", ["ja"] = "いま書いているものを貼ってください — 顧客向けのページでも、戦略メモでも。この端末の中だけで読み、気づいた点を返し、そのまま破棄します。保存も編集もしません。", ["zh"] = "把你正在写的内容贴进来——给客户的页面、策略备忘。它只在本设备上被阅读、给出意见，然后丢弃：不保存，也不改动。", ["hi"] = "आप जिस पर काम कर रहे हैं उसे यहाँ चिपकाइए — ग्राहक के लिए पन्ना, रणनीति नोट। यह इसी डिवाइस पर पढ़ा जाता है, टिप्पणी दी जाती है, और छोड़ दिया जाता है: कुछ भी सहेजा या बदला नहीं जाता।", ["ar"] = "الصق ما تعمل عليه — صفحة لعميل، مذكرة استراتيجية. يُقرأ هنا على هذا الجهاز، ويُعلَّق عليه، ثم يُطرح: لا يُحفظ شيء ولا يُعدَّل شيء." },
