        ["cont.nothing"] = new() { ["en"] = "Nothing yet.", ["es"] = "Todavía nada.", ["fr"] = "Rien pour l'instant.", ["de"] = "Noch nichts.", ["pt"] = "Ainda nada.", ["it"] = "Ancora niente.", ["ja"] = "まだ何もありません。", ["zh"] = "暂时还没有。", ["hi"] = "अभी कुछ नहीं।", ["ar"] = "لا شيء بعد." },
        ["alarm.none"] = new() { ["en"] = "Nothing open.", ["es"] = "Nada abierto.", ["fr"] = "Rien en cours.", ["de"] = "Nichts offen.", ["pt"] = "Nada aberto.", ["it"] = "Niente in corso.", ["ja"] = "未対応のものはありません。", ["zh"] = "没有未处理的警报。", ["hi"] = "कुछ भी लंबित नहीं है।", ["ar"] = "لا يوجد شيء مفتوح." },
        ["alarm.lead"] = new() { ["en"] = "An alarm appears here when somebody scans the care code on your door. Scanning it does not call an ambulance — it wakes the people watching over you, and one of them has to answer.", ["es"] = "Aquí aparece una alarma cuando alguien escanea el código de cuidado de tu puerta. Escanearlo no llama a una ambulancia: despierta a las personas que te cuidan, y una de ellas tiene que responder.", ["fr"] = "Une alerte apparaît ici lorsque quelqu'un scanne le code de soins sur votre porte. Le scanner n'appelle pas d'ambulance : cela réveille les personnes qui veillent sur vous, et l'une d'elles doit répondre.", ["de"] = "Hier erscheint ein Alarm, wenn jemand den Pflegecode an Ihrer Tür scannt. Das Scannen ruft keinen Krankenwagen — es weckt die Menschen, die über Sie wachen, und eine von ihnen muss antworten.", ["pt"] = "Um alarme aparece aqui quando alguém digitaliza o código de cuidado na sua porta. Digitalizá-lo não chama uma ambulância — desperta as pessoas que velam por si, e uma delas tem de responder.", ["it"] = "Qui compare un allarme quando qualcuno scansiona il codice di assistenza sulla tua porta. Scansionarlo non chiama un'ambulanza: sveglia le persone che vegliano su di te, e una di loro deve rispondere.", ["ja"] = "誰かが玄関のケアコードを読み取ると、ここにアラームが表示されます。読み取っても救急車は呼ばれません。あなたを見守る人たちに知らせが届き、そのうちの誰かが応答しなければなりません。", ["zh"] = "当有人扫描你门上的照护码时，这里会出现一条警报。扫描不会呼叫救护车 — 它会唤醒守护你的人，其中一人必须作出回应。", ["hi"] = "जब कोई आपके दरवाज़े पर लगे केयर कोड को स्कैन करता है, तो यहाँ एक अलार्म दिखता है। स्कैन करने से एम्बुलेंस नहीं बुलाई जाती — इससे आपकी देखभाल करने वाले लोग जागते हैं, और उनमें से किसी एक को जवाब देना होता है।", ["ar"] = "يظهر هنا إنذار عندما يمسح أحدهم رمز الرعاية على بابك. المسح لا يستدعي سيارة إسعاف — بل ينبّه من يسهرون على رعايتك، وعلى أحدهم أن يستجيب." },
        ["alarm.raised"] = new() { ["en"] = "Someone raised this", ["es"] = "Alguien lo ha activado", ["fr"] = "Quelqu'un a déclenché ceci", ["de"] = "Jemand hat dies ausgelöst", ["pt"] = "Alguém accionou isto", ["it"] = "Qualcuno ha attivato questo", ["ja"] = "誰かがこれを知らせました", ["zh"] = "有人发出了这条警报", ["hi"] = "किसी ने यह उठाया है", ["ar"] = "أطلق أحدهم هذا الإنذار" },
        ["alarm.attending"] = new() { ["en"] = "{who} is attending — still open, not resolved.", ["es"] = "{who} está atendiendo — sigue abierto, no resuelto.", ["fr"] = "{who} intervient — toujours en cours, non résolu.", ["de"] = "{who} kümmert sich darum — weiterhin offen, nicht erledigt.", ["pt"] = "{who} está a atender — ainda aberto, não resolvido.", ["it"] = "{who} se ne sta occupando — ancora aperto, non risolto.", ["ja"] = "{who} が対応中です — まだ解決していません。", ["zh"] = "{who} 正在处理 — 仍未关闭，尚未解决。", ["hi"] = "{who} देख रहे हैं — अभी भी खुला है, हल नहीं हुआ।", ["ar"] = "{who} يتولى الأمر — لا يزال مفتوحًا وغير مُنتهٍ." },
        ["alarm.going"] = new() { ["en"] = "I have this — I'm going", ["es"] = "Yo me encargo — voy en camino", ["fr"] = "Je m'en occupe — j'y vais", ["de"] = "Ich übernehme das — ich gehe hin", ["pt"] = "Eu trato disto — vou a caminho", ["it"] = "Me ne occupo io — sto andando", ["ja"] = "私が対応します — 向かいます", ["zh"] = "我来处理 — 我这就过去", ["hi"] = "मैं देख लेता हूँ — मैं जा रहा हूँ", ["ar"] = "سأتولى الأمر — أنا في طريقي" },
        ["alarm.cannot_go"] = new() { ["en"] = "Nobody can go — escalate", ["es"] = "Nadie puede ir — escalar", ["fr"] = "Personne ne peut y aller — escalader", ["de"] = "Niemand kann hin — eskalieren", ["pt"] = "Ninguém pode ir — escalar", ["it"] = "Nessuno può andare — inoltra", ["ja"] = "誰も行けません — 上位に上げる", ["zh"] = "没有人能过去 — 升级处理", ["hi"] = "कोई नहीं जा सकता — आगे बढ़ाएँ", ["ar"] = "لا أحد يستطيع الذهاب — صعِّد الأمر" },
        ["alarm.clear"] = new() { ["en"] = "It's over — clear it", ["es"] = "Ya pasó — cerrarlo", ["fr"] = "C'est terminé — clôturer", ["de"] = "Es ist vorbei — schließen", ["pt"] = "Já passou — encerrar", ["it"] = "È finita — chiudi", ["ja"] = "解決しました — 解除する", ["zh"] = "已经结束 — 关闭警报", ["hi"] = "यह खत्म हो गया — इसे बंद करें", ["ar"] = "انتهى الأمر — أغلِق الإنذار" },
        ["alarm.not_emergency"] = new() { ["en"] = "This is not an emergency service. If it is one, call your local emergency number — this screen cannot.", ["es"] = "Esto no es un servicio de emergencias. Si lo es, llama al número de emergencias de tu zona — esta pantalla no puede hacerlo.", ["fr"] = "Ceci n'est pas un service d'urgence. S'il s'agit d'une urgence, appelez votre numéro d'urgence local — cet écran ne le peut pas.", ["de"] = "Dies ist kein Notdienst. Wenn es ein Notfall ist, rufen Sie Ihre örtliche Notrufnummer an — dieser Bildschirm kann das nicht.", ["pt"] = "Isto não é um serviço de emergência. Se for uma emergência, ligue para o número de emergência local — este ecrã não o pode fazer.", ["it"] = "Questo non è un servizio di emergenza. Se lo è, chiama il numero di emergenza locale — questa schermata non può farlo.", ["ja"] = "これは緊急通報サービスではありません。緊急の場合は地域の緊急通報番号に電話してください。この画面では通報できません。", ["zh"] = "这不是紧急服务。如果情况紧急，请拨打当地的急救电话 — 本屏幕无法代为拨打。", ["hi"] = "यह आपातकालीन सेवा नहीं है। यदि यह आपात स्थिति है, तो अपने स्थानीय आपातकालीन नंबर पर कॉल करें — यह स्क्रीन ऐसा नहीं कर सकती।", ["ar"] = "هذه ليست خدمة طوارئ. إذا كانت حالة طارئة، فاتصل برقم الطوارئ المحلي — فهذه الشاشة لا تستطيع ذلك." },
        ["alarm.asking"] = new() { ["en"] = "JIM is asking: are you okay?", ["es"] = "JIM pregunta: ¿estás bien?", ["fr"] = "JIM demande : est-ce que ça va ?", ["de"] = "JIM fragt: Geht es Ihnen gut?", ["pt"] = "O JIM pergunta: está bem?", ["it"] = "JIM chiede: stai bene?", ["ja"] = "JIM が確認しています：大丈夫ですか？", ["zh"] = "JIM 在询问：你还好吗？", ["hi"] = "JIM पूछ रहा है: क्या आप ठीक हैं?", ["ar"] = "يسأل JIM: هل أنت بخير؟" },
        ["alarm.concern"] = new() { ["en"] = "A concerning reading came in ({concern}). Attempt {n} of {total} — silence sends help.", ["es"] = "Llegó una lectura preocupante ({concern}). Intento {n} de {total} — el silencio envía ayuda.", ["fr"] = "Une mesure préoccupante est arrivée ({concern}). Tentative {n} sur {total} — le silence déclenche les secours.", ["de"] = "Ein besorgniserregender Messwert ist eingegangen ({concern}). Versuch {n} von {total} — Schweigen schickt Hilfe.", ["pt"] = "Chegou uma leitura preocupante ({concern}). Tentativa {n} de {total} — o silêncio envia ajuda.", ["it"] = "È arrivata una misurazione preoccupante ({concern}). Tentativo {n} di {total} — il silenzio manda aiuto.", ["ja"] = "気がかりな測定値が届きました（{concern}）。{total} 回中 {n} 回目の確認です — 応答がなければ助けを呼びます。", ["zh"] = "收到一项令人担忧的读数（{concern}）。第 {n} 次询问，共 {total} 次 — 若无回应将请求援助。", ["hi"] = "एक चिंताजनक रीडिंग आई है ({concern})। {total} में से {n} प्रयास — चुप्पी मदद भेज देगी।", ["ar"] = "وردت قراءة مقلقة ({concern}). المحاولة {n} من {total} — الصمت يستدعي المساعدة." },
        ["alarm.im_okay"] = new() { ["en"] = "I'm okay", ["es"] = "Estoy bien", ["fr"] = "Ça va", ["de"] = "Mir geht es gut", ["pt"] = "Estou bem", ["it"] = "Sto bene", ["ja"] = "大丈夫です", ["zh"] = "我没事", ["hi"] = "मैं ठीक हूँ", ["ar"] = "أنا بخير" },
        ["sos"] = new() { ["en"] = "SOS", ["es"] = "SOS", ["fr"] = "SOS", ["de"] = "SOS", ["pt"] = "SOS", ["it"] = "SOS", ["ja"] = "SOS", ["zh"] = "SOS", ["hi"] = "SOS", ["ar"] = "استغاثة" },
        ["sos.click"] = new() { ["en"] = "Click for emergency", ["es"] = "Haz clic para una emergencia", ["fr"] = "Cliquez en cas d'urgence", ["de"] = "Für den Notfall klicken", ["pt"] = "Clique em caso de emergência", ["it"] = "Fai clic in caso di emergenza", ["ja"] = "緊急時はクリック", ["zh"] = "紧急情况请点击", ["hi"] = "आपात स्थिति में क्लिक करें", ["ar"] = "انقر عند الطوارئ" },
        ["sos.where"] = new() { ["en"] = "Where are you? (optional)", ["es"] = "¿Dónde estás? (opcional)", ["fr"] = "Où êtes-vous ? (facultatif)", ["de"] = "Wo bist du? (optional)", ["pt"] = "Onde está? (opcional)", ["it"] = "Dove sei? (facoltativo)", ["ja"] = "どこにいますか？（任意）", ["zh"] = "你在哪里？（可选）", ["hi"] = "आप कहाँ हैं? (वैकल्पिक)", ["ar"] = "أين أنت؟ (اختياري)" },
        ["sos.what"] = new() { ["en"] = "What's happening? (optional)", ["es"] = "¿Qué está pasando? (opcional)", ["fr"] = "Que se passe-t-il ? (facultatif)", ["de"] = "Was ist los? (optional)", ["pt"] = "O que se passa? (opcional)", ["it"] = "Cosa sta succedendo? (facoltativo)", ["ja"] = "何が起きていますか？（任意）", ["zh"] = "发生了什么？（可选）", ["hi"] = "क्या हो रहा है? (वैकल्पिक)", ["ar"] = "ماذا يجري؟ (اختياري)" },
        ["sos.whatdo"] = new() { ["en"] = "What do I do?", ["es"] = "¿Qué hago?", ["fr"] = "Que dois-je faire ?", ["de"] = "Was soll ich tun?", ["pt"] = "O que faço?", ["it"] = "Cosa faccio?", ["ja"] = "どうすればいいですか？", ["zh"] = "我该怎么做？", ["hi"] = "मैं क्या करूँ?", ["ar"] = "ماذا أفعل؟" },
        ["sos.ask"] = new() { ["en"] = "Ask", ["es"] = "Preguntar", ["fr"] = "Demander", ["de"] = "Fragen", ["pt"] = "Perguntar", ["it"] = "Chiedi", ["ja"] = "たずねる", ["zh"] = "询问", ["hi"] = "पूछें", ["ar"] = "اسأل" },
        ["cw"] = new() { ["en"] = "Crash watch", ["es"] = "Vigilancia de caídas", ["fr"] = "Veille d'accident", ["de"] = "Sturzwache", ["pt"] = "Vigilância de queda", ["it"] = "Sorveglianza incidenti", ["ja"] = "クラッシュウォッチ", ["zh"] = "跌倒守护", ["hi"] = "क्रैश वॉच", ["ar"] = "مراقبة الحوادث" },
        ["cw.arm"] = new() { ["en"] = "Arm the crash watch", ["es"] = "Activar la vigilancia de caídas", ["fr"] = "Armer la veille d'accident", ["de"] = "Sturzwache scharfschalten", ["pt"] = "Armar a vigilância de queda", ["it"] = "Attiva la sorveglianza incidenti", ["ja"] = "クラッシュウォッチを作動させる", ["zh"] = "启用跌倒守护", ["hi"] = "क्रैश वॉच सक्रिय करें", ["ar"] = "فعّل مراقبة الحوادث" },
        ["cw.disarm"] = new() { ["en"] = "Disarm", ["es"] = "Desactivar", ["fr"] = "Désarmer", ["de"] = "Entschärfen", ["pt"] = "Desarmar", ["it"] = "Disattiva", ["ja"] = "解除する", ["zh"] = "停用", ["hi"] = "निष्क्रिय करें", ["ar"] = "ألغِ التفعيل" },
        ["cw.sub"] = new() { ["en"] = "Off by default, programmed by you: a critical reading (a fall the watch felt, a collapsing pulse) opens “are you okay?” — unanswered attempts contact your trusted person, and emergency services only if you tick the box. Gentle drift check-ins can never trigger this.", ["es"] = "Desactivada por defecto y configurada por ti: una lectura crítica (una caída que el reloj notó, un pulso que se desploma) abre «¿estás bien?»; si no respondes, se contacta a tu persona de confianza, y a los servicios de emergencia solo si marcas la casilla. Las comprobaciones suaves por desviación nunca pueden dispararla.", ["fr"] = "Désactivée par défaut et programmée par vous : une mesure critique (une chute ressentie par la montre, un pouls qui s'effondre) ouvre « ça va ? » — sans réponse, votre personne de confiance est contactée, et les secours seulement si vous cochez la case. Les vérifications douces de dérive ne peuvent jamais la déclencher.", ["de"] = "Standardmäßig aus und von dir eingestellt: Ein kritischer Messwert (ein Sturz, den die Uhr gespürt hat, ein einbrechender Puls) öffnet „Alles in Ordnung?“ — bleiben die Versuche unbeantwortet, wird deine Vertrauensperson benachrichtigt, und der Rettungsdienst nur, wenn du das Kästchen setzt. Sanfte Abweichungs-Check-ins können das nie auslösen.", ["pt"] = "Desligada por omissão e programada por si: uma leitura crítica (uma queda que o relógio sentiu, um pulso a colapsar) abre «está bem?» — se não responder, contacta-se a sua pessoa de confiança, e os serviços de emergência só se assinalar a caixa. As verificações suaves de desvio nunca a podem disparar.", ["it"] = "Disattivata di default e impostata da te: una misurazione critica (una caduta che l'orologio ha sentito, un polso che crolla) apre «tutto bene?» — se non rispondi viene contattata la tua persona di fiducia, e i soccorsi solo se spunti la casella. I check-in leggeri sulla deriva non possono mai farla scattare.", ["ja"] = "既定では切ってあり、設定するのはあなたです。重大な測定値（時計が感じた転倒、急落する脈）が「大丈夫ですか？」を開き、応答がなければ信頼する人に連絡します。緊急サービスへの連絡は、あなたがチェックを入れた場合だけです。穏やかなドリフトの確認がこれを引き起こすことはありません。", ["zh"] = "默认关闭，由你来设定：一次危急读数（手表感知到的跌倒、骤降的脉搏）会弹出「你还好吗？」— 若无人应答，会联系你的信任联系人；只有你勾选了，才会联系紧急服务。温和的偏移问候永远不会触发它。", ["hi"] = "डिफ़ॉल्ट रूप से बंद, और इसे आप ही तय करते हैं: कोई गंभीर रीडिंग (घड़ी को महसूस हुआ गिरना, गिरती हुई नब्ज़) «क्या आप ठीक हैं?» खोलती है — उत्तर न मिलने पर आपके भरोसेमंद व्यक्ति से संपर्क होता है, और आपातकालीन सेवाओं से केवल तभी जब आपने वह विकल्प चुना हो। हल्के ड्रिफ़्ट चेक-इन इसे कभी सक्रिय नहीं कर सकते।", ["ar"] = "مُعطَّلة افتراضيًا وأنت من يضبطها: قراءة حرجة (سقطة شعرت بها الساعة، نبض ينهار) تفتح «هل أنت بخير؟» — وإن لم تُجب جرى الاتصال بشخصك الموثوق، وبخدمات الطوارئ فقط إن أشّرت على ذلك. ولا يمكن لاطمئنانات الانحراف اللطيفة أن تُطلقها أبدًا." },
        ["cw.sensitivity"] = new() { ["en"] = "Sensitivity", ["es"] = "Sensibilidad", ["fr"] = "Sensibilité", ["de"] = "Empfindlichkeit", ["pt"] = "Sensibilidade", ["it"] = "Sensibilità", ["ja"] = "感度", ["zh"] = "灵敏度", ["hi"] = "संवेदनशीलता", ["ar"] = "الحساسية" },
        ["cw.sensitivity.sub"] = new() { ["en"] = "Cautious escalates a rung earlier; assertive a rung later. Crisis language and critical events have floors no dial can lower.", ["es"] = "Cauteloso sube un peldaño antes; asertivo, uno después. El lenguaje de crisis y los eventos críticos tienen mínimos que ningún control puede bajar.", ["fr"] = "Prudent monte d'un cran plus tôt ; affirmé, d'un cran plus tard. Le langage de crise et les événements critiques ont des planchers qu'aucun réglage n'abaisse.", ["de"] = "Vorsichtig eskaliert eine Stufe früher, bestimmt eine Stufe später. Krisensprache und kritische Ereignisse haben Untergrenzen, die kein Regler senkt.", ["pt"] = "Cauteloso sobe um degrau mais cedo; assertivo, um mais tarde. A linguagem de crise e os eventos críticos têm mínimos que nenhum controlo baixa.", ["it"] = "Cauto sale di un gradino prima; assertivo di uno dopo. Il linguaggio di crisi e gli eventi critici hanno soglie minime che nessuna manopola abbassa.", ["ja"] = "「慎重」は一段早く、「積極」は一段遅く上げます。危機を示す言葉と重大な事象には、どのつまみでも下げられない下限があります。", ["zh"] = "「谨慎」提前一级升级，「果断」推后一级。危机性言语和危急事件都有任何旋钮都无法调低的下限。", ["hi"] = "«सतर्क» एक पायदान पहले बढ़ाता है; «दृढ़» एक पायदान बाद में। संकट की भाषा और गंभीर घटनाओं की ऐसी न्यूनतम सीमाएँ हैं जिन्हें कोई डायल नीचे नहीं कर सकता।", ["ar"] = "«الحذر» يصعّد درجةً أبكر، و«الحازم» درجةً أمتأخر. ولغة الأزمة والأحداث الحرجة لها حدود دنيا لا يخفضها أي مؤشر." },
        ["cw.cautious"] = new() { ["en"] = "cautious", ["es"] = "cauteloso", ["fr"] = "prudent", ["de"] = "vorsichtig", ["pt"] = "cauteloso", ["it"] = "cauto", ["ja"] = "慎重", ["zh"] = "谨慎", ["hi"] = "सतर्क", ["ar"] = "حذر" },
        ["cw.balanced"] = new() { ["en"] = "balanced", ["es"] = "equilibrado", ["fr"] = "équilibré", ["de"] = "ausgewogen", ["pt"] = "equilibrado", ["it"] = "equilibrato", ["ja"] = "標準", ["zh"] = "均衡", ["hi"] = "संतुलित", ["ar"] = "متوازن" },
