        ["cw.attempts"] = new() { ["en"] = "Attempts (1–10)", ["es"] = "Intentos (1–10)", ["fr"] = "Tentatives (1–10)", ["de"] = "Versuche (1–10)", ["pt"] = "Tentativas (1–10)", ["it"] = "Tentativi (1–10)", ["ja"] = "試行回数（1〜10）", ["zh"] = "尝试次数（1–10）", ["hi"] = "प्रयास (1–10)", ["ar"] = "المحاولات (1–10)" },
