        ["wel.terms"] = new() { ["en"] = "By enrolling you agree to the Terms of Service — JIM-mini is a wellness tool, not a medical device; in an emergency call 911 first. You assume the risks of AI guidance and monitoring. Full terms: GET /terms · docs/terms.md", ["es"] = "Al inscribirte aceptas los Términos del Servicio — JIM-mini es una herramienta de bienestar, no un dispositivo médico; en una emergencia llama primero al 911. Asumes los riesgos de la guía y la monitorización por IA. Términos completos: GET /terms · docs/terms.md", ["fr"] = "En vous inscrivant, vous acceptez les Conditions d'utilisation — JIM-mini est un outil de bien-être, pas un dispositif médical ; en cas d'urgence, appelez d'abord le 911. Vous assumez les risques du guidage et de la surveillance par IA. Conditions complètes : GET /terms · docs/terms.md", ["de"] = "Mit der Anmeldung stimmen Sie den Nutzungsbedingungen zu — JIM-mini ist ein Wellness-Werkzeug, kein Medizinprodukt; im Notfall zuerst 911 anrufen. Sie tragen die Risiken von KI-Anleitung und -Überwachung. Vollständige Bedingungen: GET /terms · docs/terms.md", ["pt"] = "Ao inscrever-se aceita os Termos de Serviço — o JIM-mini é uma ferramenta de bem-estar, não um dispositivo médico; numa emergência ligue primeiro ao 911. Assume os riscos da orientação e monitorização por IA. Termos completos: GET /terms · docs/terms.md", ["it"] = "Iscrivendoti accetti i Termini di Servizio — JIM-mini è uno strumento di benessere, non un dispositivo medico; in emergenza chiama prima il 911. Ti assumi i rischi della guida e del monitoraggio dell'IA. Termini completi: GET /terms · docs/terms.md", ["ja"] = "登録すると利用規約に同意したことになります — JIM-miniはウェルネスツールであり医療機器ではありません。緊急時はまず911に電話してください。AIによる案内と見守りのリスクはご自身が負います。全文: GET /terms · docs/terms.md", ["zh"] = "注册即表示你同意服务条款 — JIM-mini 是健康工具，不是医疗设备；紧急情况请先拨打911。你自行承担AI指导与监测的风险。完整条款：GET /terms · docs/terms.md", ["hi"] = "नामांकन करके आप सेवा की शर्तें स्वीकार करते हैं — JIM-mini एक वेलनेस उपकरण है, चिकित्सा उपकरण नहीं; आपात स्थिति में पहले 911 पर कॉल करें। AI मार्गदर्शन और निगरानी के जोखिम आप स्वयं उठाते हैं। पूरी शर्तें: GET /terms · docs/terms.md", ["ar"] = "بالتسجيل توافق على شروط الخدمة — JIM-mini أداة عافية وليست جهازًا طبيًا؛ في الطوارئ اتصل أولًا بالرقم 911. أنت تتحمل مخاطر الإرشاد والمراقبة بالذكاء الاصطناعي. الشروط الكاملة: GET /terms · docs/terms.md" },
        ["wel.backend"] = new() { ["en"] = "Start the backend:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["es"] = "Arranca el backend:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["fr"] = "Démarrez le backend :  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["de"] = "Backend starten:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["pt"] = "Inicie o backend:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["it"] = "Avvia il backend:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["ja"] = "バックエンドを起動:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["zh"] = "启动后端：  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["hi"] = "बैकएंड शुरू करें:  JIM_CORS_ORIGINS=* uvicorn jim.api:app", ["ar"] = "شغّل الخادم الخلفي:  JIM_CORS_ORIGINS=* uvicorn jim.api:app" },
