        ["mid.sub"] = new() { ["en"] = "A shareable card for first responders: condition-level facts only, readable from a locked phone. Re-issuing rotates the QR and kills the old one.", ["es"] = "Una tarjeta compartible para el personal de emergencias: solo datos de nivel clínico, legible desde un teléfono bloqueado. Volver a emitirla rota el QR y anula el anterior.", ["fr"] = "Une fiche partageable pour les secouristes : uniquement des faits de niveau clinique, lisible depuis un téléphone verrouillé. La réémettre fait tourner le QR et annule l'ancien.", ["de"] = "Eine teilbare Karte für Ersthelfer: nur Angaben auf Befundebene, vom gesperrten Telefon lesbar. Ein erneutes Ausstellen wechselt den QR-Code und macht den alten ungültig.", ["pt"] = "Um cartão partilhável para os primeiros socorros: apenas factos de nível clínico, legível a partir de um telefone bloqueado. Reemitir roda o QR e anula o anterior.", ["it"] = "Una scheda condivisibile per i soccorritori: solo dati di livello clinico, leggibile da un telefono bloccato. Riemetterla ruota il QR e annulla il precedente.", ["ja"] = "救急対応者に渡せるカードです。記載は病態レベルの事実のみで、ロックされた端末からでも読めます。再発行すると QR が更新され、古いものは無効になります。", ["zh"] = "一张可交给急救人员的卡片：只含病情层面的事实，锁屏状态下也能读取。重新签发会更换二维码并作废旧的。", ["hi"] = "प्राथमिक उत्तरदाताओं के लिए साझा किया जा सकने वाला कार्ड: केवल स्थिति-स्तर के तथ्य, लॉक फ़ोन से भी पढ़ने योग्य। दोबारा जारी करने पर QR बदल जाता है और पुराना रद्द हो जाता है।", ["ar"] = "بطاقة يمكن مشاركتها مع المسعفين: حقائق على مستوى الحالة فقط، وتُقرأ من هاتف مقفل. وإعادة الإصدار تُبدّل رمز الاستجابة وتُبطل القديم." },
