        ["rob.sub"] = new() { ["en"] = "Bound robots respond to escalations: mobile bodies come to you; vacuums dock and clear the floor.", ["es"] = "Los robots vinculados responden a las escaladas: los cuerpos móviles acuden a ti; las aspiradoras se acoplan y despejan el suelo.", ["fr"] = "Les robots liés répondent aux escalades : les corps mobiles viennent à vous ; les aspirateurs se remettent en base et dégagent le sol.", ["de"] = "Gebundene Roboter reagieren auf Eskalationen: mobile Körper kommen zu dir, Sauger docken an und räumen den Boden frei.", ["pt"] = "Os robôs vinculados respondem às escaladas: os corpos móveis vão ter consigo; os aspiradores acoplam e libertam o chão.", ["it"] = "I robot collegati rispondono alle escalation: i corpi mobili vengono da te; gli aspirapolvere tornano alla base e liberano il pavimento.", ["ja"] = "結び付けたロボットは段階上昇に応じます。動く身体はあなたのもとへ向かい、掃除機はドックに戻って床を空けます。", ["zh"] = "已绑定的机器人会响应升级：可移动的躯体会赶到你身边，扫地机则回座并清空地面。", ["hi"] = "जुड़े हुए रोबोट एस्केलेशन पर प्रतिक्रिया देते हैं: चलने वाले शरीर आपके पास आते हैं; वैक्यूम डॉक पर लौटकर फ़र्श ख़ाली कर देते हैं।", ["ar"] = "الآليّات المرتبطة تستجيب للتصعيد: الأجسام المتحركة تأتي إليك، والمكانس تعود إلى قواعدها وتُخلي الأرض." },
