        ["hld.take.pitch"] = new() { ["en"] = "Everything this deployment holds about you, as one file. Live credentials are left out — the rest is yours.", ["es"] = "Todo lo que esta instalación tiene sobre ti, en un archivo. Las credenciales activas quedan fuera; el resto es tuyo.", ["fr"] = "Tout ce que ce déploiement détient sur vous, en un fichier. Les identifiants actifs sont exclus ; le reste est à vous.", ["de"] = "Alles, was diese Installation über Sie hat, als eine Datei. Aktive Zugangsdaten bleiben draußen — der Rest gehört Ihnen.", ["pt"] = "Tudo o que esta instalação tem sobre si, num ficheiro. As credenciais activas ficam de fora; o resto é seu.", ["it"] = "Tutto ciò che questa installazione ha su di te, in un file. Le credenziali attive restano fuori; il resto è tuo.", ["ja"] = "この導入があなたについて保持しているすべてを一つのファイルに。有効な資格情報は含みません。", ["zh"] = "本部署持有的关于您的全部内容，汇成一个文件。不含有效凭据，其余都是您的。", ["hi"] = "यह परिनियोजन आपके बारे में जो कुछ रखता है, एक फ़ाइल में। सक्रिय क्रेडेंशियल शामिल नहीं।", ["ar"] = "كل ما يحتفظ به هذا النشر عنك، في ملف واحد. لا تُدرج بيانات الاعتماد الفعّالة." },
