        ["hld.end"] = new() { ["en"] = "End it", ["es"] = "Terminar con todo", ["fr"] = "Y mettre fin", ["de"] = "Beenden", ["pt"] = "Acabar com tudo", ["it"] = "Metterci fine", ["ja"] = "すべて終わらせる", ["zh"] = "结束这一切", ["hi"] = "इसे समाप्त करें", ["ar"] = "أنهِ كل شيء" },
        ["hld.end.pitch"] = new() { ["en"] = "Erases everything held about you on this deployment. There is no undo, which is the point of it. Type erase to arm the button.", ["es"] = "Borra todo lo que se guarda sobre ti en este despliegue. No hay deshacer, y ese es justamente el punto. Escribe erase para armar el botón.", ["fr"] = "Efface tout ce qui est détenu sur vous sur ce déploiement. Il n'y a pas d'annulation, et c'est justement le but. Tapez erase pour armer le bouton.", ["de"] = "Löscht alles, was auf diesem Deployment über Sie gehalten wird. Es gibt kein Rückgängig, und genau darum geht es. Tippen Sie erase, um den Knopf scharf zu stellen.", ["pt"] = "Apaga tudo o que é guardado sobre si neste deployment. Não há como desfazer, e é essa a intenção. Escreva erase para armar o botão.", ["it"] = "Cancella tutto ciò che è custodito su di te in questo deployment. Non c'è annullamento, ed è proprio il punto. Digita erase per armare il pulsante.", ["ja"] = "この配備であなたについて保持されているすべてを消去します。取り消しはできません — それがこの機能の意味です。ボタンを有効にするには erase と入力してください。", ["zh"] = "抹除本部署上关于你的一切。没有撤销，这正是它的意义所在。输入 erase 以启用该按钮。", ["hi"] = "इस डिप्लॉयमेंट पर आपके बारे में रखा सब कुछ मिटा देता है। कोई पूर्ववत नहीं, और यही इसका मक़सद है। बटन सक्रिय करने के लिए erase टाइप करें।", ["ar"] = "يمحو كل ما هو محفوظ عنك على هذا النشر. لا تراجع، وهذا هو المقصود. اكتب erase لتفعيل الزر." },
        ["hld.end.ph"] = new() { ["en"] = "erase", ["es"] = "erase", ["fr"] = "erase", ["de"] = "erase", ["pt"] = "erase", ["it"] = "erase", ["ja"] = "erase", ["zh"] = "erase", ["hi"] = "erase", ["ar"] = "erase" },
        ["hld.end.go"] = new() { ["en"] = "Erase everything", ["es"] = "Borrarlo todo", ["fr"] = "Tout effacer", ["de"] = "Alles löschen", ["pt"] = "Apagar tudo", ["it"] = "Cancella tutto", ["ja"] = "すべて消去", ["zh"] = "抹除一切", ["hi"] = "सब कुछ मिटाएँ", ["ar"] = "امحُ كل شيء" },
        ["hld.end.gone"] = new() { ["en"] = "Erased. This deployment holds nothing about you.", ["es"] = "Borrado. Esta instalación no guarda nada sobre ti.", ["fr"] = "Effacé. Ce déploiement ne détient plus rien sur vous.", ["de"] = "Gelöscht. Diese Installation hält nichts mehr über Sie.", ["pt"] = "Apagado. Esta instalação já não guarda nada sobre si.", ["it"] = "Cancellato. Questa installazione non conserva più nulla su di te.", ["ja"] = "消去しました。この導入はあなたについて何も保持していません。", ["zh"] = "已抹除。本部署不再持有你的任何内容。", ["hi"] = "मिटा दिया गया। यह परिनियोजन आपके बारे में कुछ नहीं रखता।", ["ar"] = "تم المحو. لم يعد هذا النشر يحتفظ بأي شيء عنك." },
        ["cust"] = new() { ["en"] = "Vault custody", ["es"] = "Custodia de la bóveda", ["fr"] = "Garde du coffre", ["de"] = "Tresor-Verwahrung", ["pt"] = "Custódia do cofre", ["it"] = "Custodia della cassaforte", ["ja"] = "保管庫の管理記録", ["zh"] = "保险库保管", ["hi"] = "वॉल्ट अभिरक्षा", ["ar"] = "حفظ الخزنة" },
        ["cust.sub"] = new() { ["en"] = "Chats with tandem specialists are sealed into the PDI vault — encrypted, attributed, and hash-chained. This is your copy of the proof.", ["es"] = "Las conversaciones con especialistas en tándem se sellan en la bóveda PDI: cifradas, atribuidas y encadenadas por hash. Esta es tu copia de la prueba.", ["fr"] = "Les échanges avec les spécialistes en tandem sont scellés dans le coffre PDI — chiffrés, attribués et chaînés par empreinte. Voici votre copie de la preuve.", ["de"] = "Gespräche mit Tandem-Fachleuten werden im PDI-Tresor versiegelt — verschlüsselt, zugeordnet und hash-verkettet. Dies ist deine Kopie des Nachweises.", ["pt"] = "As conversas com especialistas em tandem são seladas no cofre PDI — cifradas, atribuídas e encadeadas por hash. Esta é a sua cópia da prova.", ["it"] = "Le conversazioni con gli specialisti in tandem sono sigillate nella cassaforte PDI — cifrate, attribuite e concatenate con hash. Questa è la tua copia della prova.", ["ja"] = "タンデムの専門家とのやり取りは PDI 保管庫に封印されます — 暗号化され、帰属が記録され、ハッシュで連結されます。これはその証跡のあなたの控えです。", ["zh"] = "与协同专家的对话会被封存进 PDI 保险库 — 加密、标明归属、以哈希相连。这是你留存的凭证副本。", ["hi"] = "टैंडेम विशेषज्ञों के साथ हुई बातचीत PDI वॉल्ट में सील की जाती है — एन्क्रिप्टेड, श्रेय-सहित और हैश-श्रृंखलाबद्ध। यह उस प्रमाण की आपकी प्रति है।", ["ar"] = "تُختم المحادثات مع الأخصائيين المرافقين في خزنة PDI — مشفّرة ومنسوبة ومتسلسلة بالتجزئة. وهذه نسختك من الإثبات." },
        ["cust.none"] = new() { ["en"] = "No sealed exchanges yet — they appear after a tandem specialist chat.", ["es"] = "Aún no hay intercambios sellados: aparecen tras una conversación con un especialista en tándem.", ["fr"] = "Aucun échange scellé pour l'instant — ils apparaissent après une conversation avec un spécialiste en tandem.", ["de"] = "Noch keine versiegelten Austausche — sie erscheinen nach einem Gespräch mit einer Tandem-Fachkraft.", ["pt"] = "Ainda sem trocas seladas — aparecem depois de uma conversa com um especialista em tandem.", ["it"] = "Ancora nessuno scambio sigillato — compaiono dopo una conversazione con uno specialista in tandem.", ["ja"] = "封印されたやり取りはまだありません。タンデムの専門家と話したあとに現れます。", ["zh"] = "尚无封存的往来 — 它们会在与协同专家对话后出现。", ["hi"] = "अभी कोई सील किया गया आदान-प्रदान नहीं — ये टैंडेम विशेषज्ञ से बातचीत के बाद दिखेंगे।", ["ar"] = "لا مبادلات مختومة بعد — تظهر بعد محادثة مع أخصائي مرافق." },
