        ["prob.none"] = new() { ["en"] = "Nothing has been reported to this server yet.", ["es"] = "Aún no se ha informado nada a este servidor.", ["fr"] = "Rien n'a encore été rapporté à ce serveur.", ["de"] = "Diesem Server wurde noch nichts gemeldet.", ["pt"] = "Ainda nada foi comunicado a este servidor.", ["it"] = "A questo server non è ancora stato segnalato nulla.", ["ja"] = "このサーバーにはまだ何も報告されていません。", ["zh"] = "尚未有任何报告到达此服务器。", ["hi"] = "इस सर्वर को अभी तक कुछ नहीं बताया गया।", ["ar"] = "لم يُبلَّغ هذا الخادم بشيء بعد." },
