        ["ns.pr.toggle"] = new() { ["en"] = "Send failure counts", ["es"] = "Enviar recuentos de fallos", ["fr"] = "Envoyer les décomptes d'échecs", ["de"] = "Fehlerzählungen senden", ["pt"] = "Enviar contagens de falhas", ["it"] = "Invia i conteggi degli errori", ["ja"] = "失敗の件数を送る", ["zh"] = "发送失败计数", ["hi"] = "विफलताओं की गिनती भेजें", ["ar"] = "أرسل أعداد الإخفاقات" },
        ["ns.pr.show"] = new() { ["en"] = "Show what would be sent", ["es"] = "Mostrar lo que se enviaría", ["fr"] = "Montrer ce qui serait envoyé", ["de"] = "Zeigen, was gesendet würde", ["pt"] = "Mostrar o que seria enviado", ["it"] = "Mostra ciò che verrebbe inviato", ["ja"] = "送られる内容を表示", ["zh"] = "查看将要发送的内容", ["hi"] = "जो भेजा जाएगा वह दिखाएँ", ["ar"] = "أظهر ما سيُرسل" },
        ["ns.pr.hide"] = new() { ["en"] = "Hide what would be sent", ["es"] = "Ocultar lo que se enviaría", ["fr"] = "Masquer ce qui serait envoyé", ["de"] = "Verbergen, was gesendet würde", ["pt"] = "Ocultar o que seria enviado", ["it"] = "Nascondi ciò che verrebbe inviato", ["ja"] = "送られる内容を隠す", ["zh"] = "隐藏将要发送的内容", ["hi"] = "जो भेजा जाएगा वह छिपाएँ", ["ar"] = "أخفِ ما سيُرسل" },
        ["res.waiver.sub"] = new() { ["en"] = "Unlock automatic operation: CPR that starts on detection, and a fully-automatic AED that shocks on its own analysis after the robot verifies everyone is clear. Until signed, every start needs an on-scene confirmation and no shock is ever delivered.", ["es"] = "Habilita el funcionamiento automático: RCP que empieza al detectarse, y un DEA totalmente automático que descarga según su propio análisis después de que el robot verifique que nadie toca a la persona. Hasta que se firme, cada inicio necesita una confirmación en el lugar y no se administra ninguna descarga.", ["fr"] = "Débloque le fonctionnement automatique : une RCP qui démarre à la détection, et un DAE entièrement automatique qui délivre le choc selon sa propre analyse une fois que le robot a vérifié que personne ne touche la victime. Tant que ce n'est pas signé, chaque démarrage exige une confirmation sur place et aucun choc n'est jamais délivré.", ["de"] = "Schaltet den automatischen Betrieb frei: eine Reanimation, die bei Erkennung beginnt, und ein vollautomatischer AED, der nach eigener Analyse schockt, sobald der Roboter geprüft hat, dass niemand die Person berührt. Bis zur Unterschrift braucht jeder Start eine Bestätigung vor Ort, und es wird nie ein Schock abgegeben.", ["pt"] = "Desbloqueia o funcionamento automático: RCP que começa ao detetar, e um DAE totalmente automático que choca segundo a sua própria análise depois de o robô verificar que ninguém está em contacto. Até ser assinado, cada início precisa de uma confirmação no local e nunca é administrado qualquer choque.", ["it"] = "Sblocca il funzionamento automatico: una RCP che parte al rilevamento e un DAE completamente automatico che eroga la scarica in base alla propria analisi dopo che il robot ha verificato che nessuno tocchi la persona. Finché non è firmata, ogni avvio richiede una conferma sul posto e non viene mai erogata alcuna scarica.", ["ja"] = "自動での作動を解除します。検知した時点で始まる心肺蘇生と、ロボットが周囲の安全を確認したうえで自身の解析にもとづいて通電する全自動 AED です。署名するまでは、開始のたびに現場での確認が必要で、通電は一切行われません。", ["zh"] = "解锁自动运行：检测到即开始的心肺复苏，以及在机器人确认所有人都已离开后、依自身分析放电的全自动 AED。在签署之前，每次启动都需要现场确认，并且绝不会放电。", ["hi"] = "स्वचालित संचालन खोलता है: पता चलते ही शुरू होने वाला सीपीआर, और एक पूर्ण-स्वचालित AED जो रोबोट द्वारा यह जाँच लेने के बाद कि सब दूर हैं, अपने ही विश्लेषण पर झटका देता है। हस्ताक्षर होने तक हर शुरुआत के लिए मौक़े पर पुष्टि चाहिए और कोई झटका कभी नहीं दिया जाता।", ["ar"] = "يفتح التشغيل التلقائي: إنعاش قلبي رئوي يبدأ عند الاكتشاف، ومزيل رجفان آلي بالكامل يصعق بناءً على تحليله الخاص بعد أن يتحقق الآلي من ابتعاد الجميع. وإلى أن يُوقَّع، تحتاج كل بداية إلى تأكيد في الموقع ولا تُعطى أي صدمة إطلاقًا." },
        ["mid.rotate"] = new() { ["en"] = "Rotate QR", ["es"] = "Rotar el QR", ["fr"] = "Renouveler le QR", ["de"] = "QR wechseln", ["pt"] = "Rodar o QR", ["it"] = "Ruota il QR", ["ja"] = "QR を更新", ["zh"] = "更换二维码", ["hi"] = "QR बदलें", ["ar"] = "بدّل رمز الاستجابة" },
        ["res.signed.by"] = new() { ["en"] = "Signed by {name} — CPR-rated robots may start compressions automatically and operate a fully-automatic AED. A shock still only follows the AED's own rhythm analysis.", ["es"] = "Firmado por {name}: los robots homologados para RCP pueden iniciar las compresiones automáticamente y manejar un DEA totalmente automático. La descarga sigue dependiendo únicamente del análisis del ritmo que hace el propio DEA.", ["fr"] = "Signé par {name} — les robots habilités RCP peuvent démarrer les compressions automatiquement et piloter un DAE entièrement automatique. Le choc ne suit toujours que la propre analyse du rythme par le DAE.", ["de"] = "Unterschrieben von {name} — für Reanimation zugelassene Roboter dürfen die Kompressionen automatisch beginnen und einen vollautomatischen AED bedienen. Ein Schock folgt weiterhin nur der eigenen Rhythmusanalyse des AED.", ["pt"] = "Assinado por {name} — os robôs homologados para RCP podem iniciar as compressões automaticamente e operar um DAE totalmente automático. O choque continua a seguir apenas a análise do ritmo feita pelo próprio DAE.", ["it"] = "Firmato da {name} — i robot abilitati alla RCP possono avviare le compressioni automaticamente e usare un DAE completamente automatico. La scarica resta subordinata alla sola analisi del ritmo fatta dal DAE.", ["ja"] = "{name} が署名しました — 心肺蘇生対応のロボットは、胸骨圧迫を自動で開始し、全自動 AED を扱えます。通電は、いまも AED 自身の心電図解析にのみ従います。", ["zh"] = "由 {name} 签署 — 具备心肺复苏资质的机器人可自动开始按压并操作全自动 AED。放电仍然只依据 AED 自身的心律分析。", ["hi"] = "{name} द्वारा हस्ताक्षरित — सीपीआर-सक्षम रोबोट अपने आप छाती दबाना शुरू कर सकते हैं और पूर्ण-स्वचालित AED चला सकते हैं। झटका फिर भी केवल AED के अपने लय-विश्लेषण के अनुसार ही दिया जाता है।", ["ar"] = "وقّعه {name} — يجوز للآليّات المؤهَّلة للإنعاش أن تبدأ الضغطات تلقائيًا وأن تشغّل مزيل رجفان آليًا بالكامل. وتظل الصدمة تابعة لتحليل الجهاز نفسه لنظم القلب لا غير." },
