        ["fam.token"] = new() { ["en"] = "Device token — shown once, put it on their watch or phone:", ["es"] = "Token del dispositivo: se muestra una sola vez; ponlo en su reloj o teléfono:", ["fr"] = "Jeton d'appareil — affiché une seule fois, mettez-le sur sa montre ou son téléphone :", ["de"] = "Gerätetoken — wird einmal angezeigt; trag ihn auf ihrer Uhr oder ihrem Telefon ein:", ["pt"] = "Token do dispositivo — mostrado uma só vez; coloque-o no relógio ou telefone dele ou dela:", ["it"] = "Token del dispositivo — mostrato una sola volta, mettilo sul suo orologio o telefono:", ["ja"] = "端末トークン — 一度だけ表示されます。お子さんの時計か携帯に登録してください：", ["zh"] = "设备令牌 — 只显示一次，请填入他们的手表或手机：", ["hi"] = "डिवाइस टोकन — केवल एक बार दिखेगा, इसे उनकी घड़ी या फ़ोन पर डालिए:", ["ar"] = "رمز الجهاز — يُعرض مرة واحدة، ضعه على ساعته أو هاتفه:" },
