        ["fam.pause.sub"] = new() { ["en"] = "Pause and quiet hours hold everyday guidance only — monitoring, crisis escalation, and the emergency path never pause.", ["es"] = "La pausa y las horas de silencio detienen solo las indicaciones cotidianas: la vigilancia, la escalada de crisis y la vía de emergencia nunca se pausan.", ["fr"] = "La pause et les heures calmes ne suspendent que les conseils du quotidien — la surveillance, l'escalade de crise et la voie d'urgence ne s'arrêtent jamais.", ["de"] = "Pause und Ruhezeiten halten nur die alltäglichen Hinweise an — Überwachung, Krisen-Eskalation und der Notfallweg pausieren nie.", ["pt"] = "A pausa e as horas de silêncio suspendem apenas as orientações do dia a dia — a vigilância, a escalada de crise e a via de emergência nunca param.", ["it"] = "La pausa e le ore di silenzio fermano solo le indicazioni quotidiane — il monitoraggio, l'escalation di crisi e la via d'emergenza non si fermano mai.", ["ja"] = "一時停止と静かな時間が止めるのは、日々の案内だけです。見守り、危機の段階上昇、緊急の経路が止まることはありません。", ["zh"] = "暂停与免打扰时段只会停下日常指导 — 监测、危机升级和紧急通路从不暂停。", ["hi"] = "विराम और शांत घंटे केवल रोज़मर्रा के मार्गदर्शन को रोकते हैं — निगरानी, संकट-वृद्धि और आपातकालीन रास्ता कभी नहीं रुकते।", ["ar"] = "الإيقاف المؤقت وساعات الهدوء تُوقف الإرشاد اليومي وحده — أما المراقبة وتصعيد الأزمات ومسار الطوارئ فلا تتوقف أبدًا." },
        ["fam.apply"] = new() { ["en"] = "Apply", ["es"] = "Aplicar", ["fr"] = "Appliquer", ["de"] = "Anwenden", ["pt"] = "Aplicar", ["it"] = "Applica", ["ja"] = "適用", ["zh"] = "应用", ["hi"] = "लागू करें", ["ar"] = "طبّق" },
        ["fam.quiet"] = new() { ["en"] = "Nothing in the window — quiet is good news.", ["es"] = "Nada en el periodo: el silencio es buena señal.", ["fr"] = "Rien sur la période — le calme est une bonne nouvelle.", ["de"] = "Nichts im Zeitraum — Ruhe ist eine gute Nachricht.", ["pt"] = "Nada no período — o silêncio é boa notícia.", ["it"] = "Niente nel periodo — il silenzio è una buona notizia.", ["ja"] = "この期間には何もありません。静かなのは良い知らせです。", ["zh"] = "这段时间没有任何记录 — 平静就是好消息。", ["hi"] = "इस अवधि में कुछ नहीं — शांति अच्छी ख़बर है।", ["ar"] = "لا شيء في هذه المدة — والهدوء خبر سار." },
