        ["jcon.sources.sub"] = new() { ["en"] = "JIM sees what you allow — flip a source off and it stops being read, immediately.", ["es"] = "JIM ve lo que tú permites: desactiva una fuente y deja de leerse de inmediato.", ["fr"] = "JIM voit ce que vous autorisez — désactivez une source et elle cesse aussitôt d'être lue.", ["de"] = "JIM sieht, was du erlaubst — schalte eine Quelle aus, und sie wird sofort nicht mehr gelesen.", ["pt"] = "O JIM vê o que você permite — desligue uma fonte e ela deixa de ser lida de imediato.", ["it"] = "JIM vede ciò che permetti — disattiva una fonte e smette subito di essere letta.", ["ja"] = "JIM が見るのは、あなたが許したものだけです。ある出どころを切れば、その時点で読まれなくなります。", ["zh"] = "JIM 只看你允许的内容 — 关掉某个来源，它立刻不再被读取。", ["hi"] = "JIM वही देखता है जिसकी आप अनुमति दें — किसी स्रोत को बंद कर दीजिए और उसे तुरंत पढ़ना बंद हो जाता है।", ["ar"] = "لا يرى JIM إلا ما تسمح به — أطفئ مصدرًا فيتوقف عن القراءة منه فورًا." },
        ["jcon.apps.sub"] = new() { ["en"] = "Apple, Google, Microsoft, and Canva apps the Guardian can collect from and act through.", ["es"] = "Aplicaciones de Apple, Google, Microsoft y Canva de las que el Guardián puede recopilar y a través de las que puede actuar.", ["fr"] = "Applications Apple, Google, Microsoft et Canva depuis lesquelles le Gardien peut collecter et par lesquelles il peut agir.", ["de"] = "Apps von Apple, Google, Microsoft und Canva, aus denen der Guardian sammeln und durch die er handeln kann.", ["pt"] = "Aplicações da Apple, Google, Microsoft e Canva das quais o Guardião pode recolher e através das quais pode agir.", ["it"] = "App di Apple, Google, Microsoft e Canva da cui il Guardiano può raccogliere e attraverso cui può agire.", ["ja"] = "Apple、Google、Microsoft、Canva のアプリ。ガーディアンはそこから集め、そこを通して動けます。", ["zh"] = "Apple、Google、Microsoft 和 Canva 的应用 — 守护者可以从中收集并经由它们行动。", ["hi"] = "Apple, Google, Microsoft और Canva के ऐप, जिनसे गार्जियन सामग्री ले सकता है और जिनके ज़रिए काम कर सकता है।", ["ar"] = "تطبيقات Apple وGoogle وMicrosoft وCanva التي يمكن للحارس الجمع منها والعمل عبرها." },
