        ["jcon.rooms.none"] = new() { ["en"] = "No rooms open right now. A community shelf that cannot load is a quiet screen, not an error.", ["es"] = "Ahora mismo no hay ninguna sala abierta. Un estante comunitario que no carga es una pantalla en silencio, no un error.", ["fr"] = "Aucune salle ouverte pour l'instant. Une étagère communautaire qui ne charge pas est un écran silencieux, pas une erreur.", ["de"] = "Gerade sind keine Räume offen. Ein Gemeinschaftsregal, das nicht lädt, ist ein stiller Bildschirm, kein Fehler.", ["pt"] = "Nenhuma sala aberta neste momento. Uma prateleira comunitária que não carrega é um ecrã silencioso, não um erro.", ["it"] = "Nessuna stanza aperta al momento. Uno scaffale comunitario che non si carica è una schermata silenziosa, non un errore.", ["ja"] = "いま開いているルームはありません。コミュニティの棚が読み込めないのは、静かな画面であってエラーではありません。", ["zh"] = "目前没有开放的房间。社区书架加载不出来，只是一块安静的屏幕，不是错误。", ["hi"] = "अभी कोई कक्ष खुला नहीं है। समुदाय की शेल्फ़ का न खुलना एक शांत स्क्रीन है, त्रुटि नहीं।", ["ar"] = "لا غرف مفتوحة الآن. ورفٌّ مجتمعي لا يُحمَّل شاشةٌ هادئة، لا خطأ." },
