        ["ov.model.sub"] = new() { ["en"] = "Which LLM powers your coaching and guidance.", ["es"] = "Qué LLM impulsa tu acompañamiento y tus indicaciones.", ["fr"] = "Quel LLM alimente votre accompagnement et vos conseils.", ["de"] = "Welches LLM dein Coaching und deine Hinweise antreibt.", ["pt"] = "Que LLM alimenta o seu acompanhamento e as suas orientações.", ["it"] = "Quale LLM alimenta il tuo coaching e le tue indicazioni.", ["ja"] = "コーチングと案内を動かしている LLM です。", ["zh"] = "为你的辅导与指导提供动力的 LLM。", ["hi"] = "कौन-सा LLM आपके कोचिंग और मार्गदर्शन को चलाता है।", ["ar"] = "أيّ نموذج لغوي يشغّل إرشادك وتدريبك." },
