        ["ns.acc"] = new() { ["en"] = "Accessibility", ["es"] = "Accesibilidad", ["fr"] = "Accessibilité", ["de"] = "Barrierefreiheit", ["pt"] = "Acessibilidade", ["it"] = "Accessibilità", ["ja"] = "アクセシビリティ", ["zh"] = "无障碍", ["hi"] = "सुलभता", ["ar"] = "إمكانية الوصول" },
        ["ns.acc.lead"] = new() { ["en"] = "Ability is not a gate. Three questions — no account, no diagnosis, no name. Your words stay on this deployment and become tracked work.", ["es"] = "La capacidad no es una puerta. Tres preguntas: sin cuenta, sin diagnóstico, sin nombre. Tus palabras se quedan en esta instalación y se convierten en trabajo registrado.", ["fr"] = "La capacité n’est pas une barrière. Trois questions — pas de compte, pas de diagnostic, pas de nom. Vos mots restent sur cette installation et deviennent du travail suivi.", ["de"] = "Fähigkeit ist kein Tor. Drei Fragen — kein Konto, keine Diagnose, kein Name. Deine Worte bleiben auf dieser Installation und werden zu verfolgter Arbeit.", ["pt"] = "Capacidade não é um portão. Três perguntas — sem conta, sem diagnóstico, sem nome. Suas palavras ficam nesta instalação e viram trabalho registrado.", ["it"] = "L’abilità non è un cancello. Tre domande: niente account, niente diagnosi, niente nome. Le tue parole restano su questa installazione e diventano lavoro tracciato.", ["ja"] = "能力は門ではありません。質問は3つ — アカウントも診断名も名前も不要です。あなたの言葉はこの環境にとどまり、追跡される作業になります。", ["zh"] = "能力不是门槛。三个问题——无需账户、无需诊断、无需姓名。你的话留在此部署中，并成为被追踪的工作。", ["hi"] = "क्षमता कोई द्वार नहीं है। तीन प्रश्न — न खाता, न निदान, न नाम। आपके शब्द इसी परिनियोजन में रहते हैं और दर्ज कार्य बन जाते हैं।", ["ar"] = "القدرة ليست بوابة. ثلاثة أسئلة — لا حساب ولا تشخيص ولا اسم. تبقى كلماتك على هذا النشر وتصبح عملًا متتبعًا." },
        ["ns.ct.title"] = new() { ["en"] = "Care Team", ["es"] = "Equipo de cuidados", ["fr"] = "Équipe de soins", ["de"] = "Betreuungsteam", ["pt"] = "Equipa de cuidados", ["it"] = "Squadra di cura", ["ja"] = "ケアチーム", ["zh"] = "照护团队", ["hi"] = "देखभाल टीम", ["ar"] = "فريق الرعاية" },
        ["ns.ct.sub"] = new() { ["en"] = "your own QRME organization, coordinated by the Guardian", ["es"] = "tu propia organización QRME, coordinada por el Guardián", ["fr"] = "votre propre organisation QRME, coordonnée par le Gardien", ["de"] = "Ihre eigene QRME-Organisation, koordiniert vom Guardian", ["pt"] = "a sua própria organização QRME, coordenada pelo Guardião", ["it"] = "la tua organizzazione QRME, coordinata dal Guardian", ["ja"] = "ガーディアンが取りまとめる、あなた自身のQRME組織", ["zh"] = "你自己的 QRME 组织，由守护者统筹", ["hi"] = "आपका अपना QRME संगठन, गार्जियन द्वारा समन्वित", ["ar"] = "منظمتك الخاصة في QRME، ينسّقها الحارس" },
        ["ns.ct.link.pitch"] = new() { ["en"] = "Found the org and staff its desks in QRME first, then paste its id, the desk that speaks for JIM, and your own QRME owner token. The token is stored for coordinations only and deleted when you unlink; it is never shown again.", ["es"] = "Funda la organización y dota sus mostradores en QRME primero, luego pega su id, el mostrador que habla por JIM, y tu propio token de propietario de QRME. El token se guarda solo para las coordinaciones y se borra al desvincular; nunca se vuelve a mostrar.", ["fr"] = "Fondez l'organisation et dotez ses comptoirs dans QRME d'abord, puis collez son id, le comptoir qui parle pour JIM, et votre propre jeton de propriétaire QRME. Le jeton n'est conservé que pour les coordinations et supprimé au moment de délier ; il n'est jamais réaffiché.", ["de"] = "Gründen Sie die Organisation und besetzen Sie ihre Schalter zuerst in QRME, fügen Sie dann ihre Id ein, den Schalter, der für JIM spricht, und Ihr eigenes QRME-Inhaber-Token. Das Token wird nur für Koordinationen gespeichert und beim Trennen gelöscht; es wird nie wieder angezeigt.", ["pt"] = "Funde a organização e preencha os seus balcões no QRME primeiro, depois cole o id dela, o balcão que fala pelo JIM, e o seu próprio token de proprietário QRME. O token é guardado só para coordenações e apagado quando desligar; nunca é mostrado outra vez.", ["it"] = "Fonda l'organizzazione e presidia i suoi banchi in QRME prima, poi incolla il suo id, il banco che parla per JIM, e il tuo token di proprietario QRME. Il token è conservato solo per i coordinamenti ed è cancellato quando scolleghi; non viene mai più mostrato.", ["ja"] = "まずQRMEで組織を設立してデスクに人を配置し、その組織ID、JIMを代弁するデスク、そしてあなた自身のQRMEオーナートークンを貼り付けてください。トークンは連携のためだけに保存され、紐付けを外すと削除されます。二度と表示されることはありません。", ["zh"] = "请先在 QRME 中创建组织并为其柜台配备人员，然后粘贴组织 id、代表 JIM 发言的柜台，以及你自己的 QRME 所有者令牌。该令牌仅为协同而保存，取消关联时即删除；且绝不会再次显示。", ["hi"] = "पहले QRME में संगठन स्थापित करें और उसकी डेस्कों पर लोग बिठाएँ, फिर उसका id, वह डेस्क जो JIM की ओर से बोलती है, और अपना QRME स्वामी टोकन चिपकाएँ। टोकन केवल समन्वय के लिए रखा जाता है और अलग करने पर मिटा दिया जाता है; यह दोबारा कभी नहीं दिखाया जाता।", ["ar"] = "أسّس المنظمة وزوّد مكاتبها في QRME أولًا، ثم الصق معرّفها، والمكتب الذي يتحدث باسم JIM، ورمز المالك الخاص بك في QRME. يُخزَّن الرمز للتنسيق فقط ويُحذف عند فك الارتباط؛ ولا يُعرض مرة أخرى أبدًا." },
        ["ns.ct.link.org"] = new() { ["en"] = "Org id", ["es"] = "Id de la organización", ["fr"] = "Id de l'organisation", ["de"] = "Organisations-Id", ["pt"] = "Id da organização", ["it"] = "Id dell'organizzazione", ["ja"] = "組織ID", ["zh"] = "组织 id", ["hi"] = "संगठन id", ["ar"] = "معرّف المنظمة" },
        ["ns.ct.link.org.ph"] = new() { ["en"] = "org_…", ["es"] = "org_…", ["fr"] = "org_…", ["de"] = "org_…", ["pt"] = "org_…", ["it"] = "org_…", ["ja"] = "org_…", ["zh"] = "org_…", ["hi"] = "org_…", ["ar"] = "org_…" },
        ["ns.ct.link.dept"] = new() { ["en"] = "Department id", ["es"] = "Id del departamento", ["fr"] = "Id du département", ["de"] = "Abteilungs-Id", ["pt"] = "Id do departamento", ["it"] = "Id del reparto", ["ja"] = "部署ID", ["zh"] = "部门 id", ["hi"] = "विभाग id", ["ar"] = "معرّف القسم" },
        ["ns.ct.link.dept.ph"] = new() { ["en"] = "dep_…", ["es"] = "dep_…", ["fr"] = "dep_…", ["de"] = "dep_…", ["pt"] = "dep_…", ["it"] = "dep_…", ["ja"] = "dep_…", ["zh"] = "dep_…", ["hi"] = "dep_…", ["ar"] = "dep_…" },
        ["ns.ct.link.token"] = new() { ["en"] = "Your QRME owner token", ["es"] = "Tu token de propietario de QRME", ["fr"] = "Votre jeton de propriétaire QRME", ["de"] = "Ihr QRME-Inhaber-Token", ["pt"] = "O seu token de proprietário QRME", ["it"] = "Il tuo token di proprietario QRME", ["ja"] = "あなたのQRMEオーナートークン", ["zh"] = "你的 QRME 所有者令牌", ["hi"] = "आपका QRME स्वामी टोकन", ["ar"] = "رمز مالك QRME الخاص بك" },
        ["ns.ct.link.token.ph"] = new() { ["en"] = "pasted, never echoed", ["es"] = "pegado, nunca mostrado", ["fr"] = "collé, jamais réaffiché", ["de"] = "eingefügt, nie wieder angezeigt", ["pt"] = "colado, nunca mostrado", ["it"] = "incollato, mai rimostrato", ["ja"] = "貼り付けるのみ、表示はされません", ["zh"] = "粘贴即可，绝不回显", ["hi"] = "चिपकाया गया, कभी दिखाया नहीं", ["ar"] = "يُلصق ولا يُعرض أبدًا" },
        ["ns.ct.link.go"] = new() { ["en"] = "Link", ["es"] = "Vincular", ["fr"] = "Lier", ["de"] = "Verknüpfen", ["pt"] = "Ligar", ["it"] = "Collega", ["ja"] = "紐付ける", ["zh"] = "关联", ["hi"] = "जोड़ें", ["ar"] = "اربط" },
        ["ns.ct.linked"] = new() { ["en"] = "Linked", ["es"] = "Vinculada", ["fr"] = "Liée", ["de"] = "Verknüpft", ["pt"] = "Ligada", ["it"] = "Collegata", ["ja"] = "紐付け済み", ["zh"] = "已关联", ["hi"] = "जुड़ा हुआ", ["ar"] = "مرتبطة" },
        ["ns.ct.linked.pitch"] = new() { ["en"] = "When a reading drifts outside your band while doses slip, the Guardian takes it to the whole team — once a day at most, on the calm path only. Summaries cross, never raw readings.", ["es"] = "Cuando una lectura se sale de tu banda mientras se saltan dosis, el Guardián lo lleva a todo el equipo — una vez al día como mucho, y solo por la vía tranquila. Cruzan resúmenes, nunca lecturas en bruto.", ["fr"] = "Quand une mesure sort de votre plage alors que des doses sont manquées, le Gardien porte l'affaire à toute l'équipe — une fois par jour au plus, et seulement par la voie calme. Ce sont des résumés qui circulent, jamais des mesures brutes.", ["de"] = "Wenn eine Messung aus Ihrem Band läuft, während Dosen ausfallen, trägt der Guardian es dem ganzen Team vor — höchstens einmal am Tag und nur auf dem ruhigen Weg. Es kreuzen Zusammenfassungen, nie Rohmessungen.", ["pt"] = "Quando uma leitura sai da sua banda enquanto falham doses, o Guardião leva-o à equipa inteira — no máximo uma vez por dia, e só pela via calma. Cruzam resumos, nunca leituras em bruto.", ["it"] = "Quando una lettura esce dalla tua banda mentre saltano le dosi, il Guardian la porta a tutta la squadra — al massimo una volta al giorno, solo sulla via calma. Passano riassunti, mai letture grezze.", ["ja"] = "服薬が抜けている最中に測定値があなたの帯を外れたとき、ガーディアンはそれをチーム全体に持ち込みます — 一日一度までで、穏やかな経路に限ります。渡るのは要約であり、生の測定値は決して渡りません。", ["zh"] = "当读数偏出你的区间、而服药又开始漏掉时，守护者会把这件事带给整个团队 — 每天至多一次，且只走平静通道。跨越的是摘要，绝非原始读数。", ["hi"] = "जब कोई रीडिंग आपके बैंड से बाहर जाए और साथ ही ख़ुराकें छूट रही हों, तो गार्जियन इसे पूरी टीम तक ले जाता है — दिन में अधिकतम एक बार, केवल शांत मार्ग से। सारांश जाते हैं, कच्ची रीडिंग कभी नहीं।", ["ar"] = "حين تنحرف قراءة خارج نطاقك بينما تُفوَّت الجرعات، يعرضها الحارس على الفريق كله — مرة في اليوم على الأكثر، وعلى المسار الهادئ فقط. تعبر الملخصات، لا القراءات الخام أبدًا." },
        ["ns.ct.linked.line"] = new() { ["en"] = "org {org} · desk {desk} · credential held", ["es"] = "org {org} · mostrador {desk} · credencial guardada", ["fr"] = "org {org} · comptoir {desk} · identifiant conservé", ["de"] = "Org {org} · Schalter {desk} · Zugang hinterlegt", ["pt"] = "org {org} · balcão {desk} · credencial guardada", ["it"] = "org {org} · banco {desk} · credenziale custodita", ["ja"] = "組織 {org} · デスク {desk} · 資格情報を保持", ["zh"] = "组织 {org} · 柜台 {desk} · 已持有凭证", ["hi"] = "संगठन {org} · डेस्क {desk} · क्रेडेंशियल रखा है", ["ar"] = "منظمة {org} · مكتب {desk} · الاعتماد محفوظ" },
        ["ns.ct.linked.goal"] = new() { ["en"] = "Take a goal to the team by hand", ["es"] = "Llevar un objetivo al equipo a mano", ["fr"] = "Porter un objectif à l'équipe à la main", ["de"] = "Ein Ziel dem Team von Hand vorlegen", ["pt"] = "Levar um objetivo à equipa à mão", ["it"] = "Porta un obiettivo alla squadra a mano", ["ja"] = "目標を手動でチームに持ち込む", ["zh"] = "手动把一个目标带给团队", ["hi"] = "कोई लक्ष्य स्वयं टीम तक ले जाएँ", ["ar"] = "خذ هدفًا إلى الفريق يدويًا" },
        ["ns.ct.linked.goal.ph"] = new() { ["en"] = "e.g. plan the recovery week", ["es"] = "p. ej. planear la semana de recuperación", ["fr"] = "p. ex. planifier la semaine de récupération", ["de"] = "z. B. die Erholungswoche planen", ["pt"] = "p. ex. planear a semana de recuperação", ["it"] = "es. pianificare la settimana di recupero", ["ja"] = "例: 回復週間の計画を立てる", ["zh"] = "例如：规划康复周", ["hi"] = "जैसे: स्वस्थ होने के सप्ताह की योजना", ["ar"] = "مثلًا: خطط لأسبوع التعافي" },
