        ["ns.ct.plans.none"] = new() { ["en"] = "No joint plans yet.", ["es"] = "Todavía no hay planes conjuntos.", ["fr"] = "Pas encore de plans conjoints.", ["de"] = "Noch keine gemeinsamen Pläne.", ["pt"] = "Ainda não há planos conjuntos.", ["it"] = "Ancora nessun piano congiunto.", ["ja"] = "共同の計画はまだありません。", ["zh"] = "尚无联合计划。", ["hi"] = "अभी कोई संयुक्त योजना नहीं।", ["ar"] = "لا خطط مشتركة بعد." },
