        ["ns.ch.mic.capped"] = new() { ["en"] = "Narrowed for the moment — a call is in progress. Your setting ({gain}) comes back afterwards.", ["es"] = "Reducido por el momento — hay una llamada en curso. Tu ajuste ({gain}) vuelve después.", ["fr"] = "Restreint pour le moment — un appel est en cours. Votre réglage ({gain}) revient ensuite.", ["de"] = "Vorübergehend verengt — ein Anruf läuft. Ihre Einstellung ({gain}) kehrt danach zurück.", ["pt"] = "Reduzido por agora — há uma chamada em curso. O seu ajuste ({gain}) volta depois.", ["it"] = "Ridotto per il momento — c'è una chiamata in corso. La tua impostazione ({gain}) torna dopo.", ["ja"] = "通話中のため一時的に絞られています。設定（{gain}）は通話後に戻ります。", ["zh"] = "通话进行中，暂时收窄。你的设置（{gain}）稍后恢复。", ["hi"] = "फ़िलहाल सीमित — कॉल चल रही है। आपकी सेटिंग ({gain}) बाद में लौट आएगी।", ["ar"] = "مقيَّد مؤقتًا — هناك مكالمة جارية. إعدادك ({gain}) يعود بعدها." },
