        ["ns.vc.mic.refused"] = new() { ["en"] = "The microphone was refused — allow it in system settings to talk to the Guardian.", ["es"] = "El micrófono fue rechazado: permítelo en los ajustes del sistema para hablar con el Guardián.", ["fr"] = "Le microphone a été refusé — autorisez-le dans les réglages du système pour parler au Gardien.", ["de"] = "Das Mikrofon wurde verweigert — erlauben Sie es in den Systemeinstellungen, um mit dem Guardian zu sprechen.", ["pt"] = "O microfone foi recusado — permita-o nas definições do sistema para falar com o Guardião.", ["it"] = "Il microfono è stato rifiutato — consentilo nelle impostazioni di sistema per parlare con il Guardian.", ["ja"] = "マイクが拒否されました — ガーディアンと話すにはシステム設定で許可してください。", ["zh"] = "麦克风被拒绝 — 请在系统设置中允许，以便与守护者对话。", ["hi"] = "माइक्रोफ़ोन अस्वीकार किया गया — गार्जियन से बात करने के लिए सिस्टम सेटिंग्स में अनुमति दें।", ["ar"] = "رُفض الميكروفون — اسمح به في إعدادات النظام للتحدث إلى الحارس." },
        ["ns.vc.device"] = new() { ["en"] = "No speaking service is configured — the device's own voice read it instead.", ["es"] = "No hay servicio de voz configurado: la propia voz del dispositivo lo leyó en su lugar.", ["fr"] = "Aucun service vocal n'est configuré — la voix de l'appareil l'a lu à la place.", ["de"] = "Kein Sprachdienst eingerichtet — die eigene Stimme des Geräts hat es stattdessen vorgelesen.", ["pt"] = "Nenhum serviço de voz configurado — a própria voz do dispositivo o leu em vez disso.", ["it"] = "Nessun servizio vocale configurato — l'ha letto la voce del dispositivo.", ["ja"] = "音声サービスが設定されていません — 代わりにデバイス自身の声が読み上げました。", ["zh"] = "未配置语音服务 — 改由设备自己的声音朗读。", ["hi"] = "कोई वाक् सेवा कॉन्फ़िगर नहीं है — इसके बजाय डिवाइस की अपनी आवाज़ ने इसे पढ़ा।", ["ar"] = "لا توجد خدمة نطق مهيأة — قرأه صوت الجهاز نفسه بدلاً من ذلك." },
