        ["rch.ask.q.ph"] = new() { ["en"] = "What do you want to know?", ["es"] = "¿Qué quieres saber?", ["fr"] = "Que voulez-vous savoir ?", ["de"] = "Was wollen Sie wissen?", ["pt"] = "O que quer saber?", ["it"] = "Cosa vuoi sapere?", ["ja"] = "何を知りたいですか？", ["zh"] = "你想知道什么？", ["hi"] = "आप क्या जानना चाहते हैं?", ["ar"] = "ماذا تريد أن تعرف؟" },
