        ["rch.ask.keep"] = new() { ["en"] = "Keep what it learned", ["es"] = "Conservar lo aprendido", ["fr"] = "Garder ce qu'il a appris", ["de"] = "Behalten, was er lernte", ["pt"] = "Guardar o que aprendeu", ["it"] = "Tieni ciò che ha imparato", ["ja"] = "学んだことを保持", ["zh"] = "保留它学到的", ["hi"] = "जो सीखा उसे रखें", ["ar"] = "احتفظ بما تعلّمه" },
        ["rch.ask.price"] = new() { ["en"] = "Redactions is how much of you was taken out before the question left, and left this host is whether it left at all. A screen that showed the findings and hid those two would be showing the answer and hiding what it cost.", ["es"] = "«Redactions» es cuánto de ti se quitó antes de que la pregunta saliera, y «left this host» es si salió siquiera. Una pantalla que mostrara los hallazgos y ocultara esos dos estaría mostrando la respuesta y escondiendo lo que costó.", ["fr"] = "« Redactions » dit combien de vous a été retiré avant que la question parte, et « left this host » dit si elle est partie tout court. Un écran qui montrerait les résultats en cachant ces deux-là montrerait la réponse en cachant son prix.", ["de"] = "»Redactions« sagt, wie viel von Ihnen entfernt wurde, bevor die Frage aufbrach, und »left this host«, ob sie überhaupt aufbrach. Ein Bildschirm, der die Befunde zeigte und diese beiden versteckte, zeigte die Antwort und verbärge ihren Preis.", ["pt"] = "«Redactions» é quanto de si foi retirado antes de a pergunta sair, e «left this host» é se sequer saiu. Um ecrã que mostrasse os resultados e escondesse esses dois estaria a mostrar a resposta e a esconder o que custou.", ["it"] = "«Redactions» è quanto di te è stato tolto prima che la domanda partisse, e «left this host» è se è partita affatto. Uno schermo che mostrasse i risultati nascondendo quei due mostrerebbe la risposta nascondendo quanto è costata.", ["ja"] = "「Redactions」は質問が出発する前にあなたのどれだけが取り除かれたかを、「left this host」はそもそも出発したかどうかを示します。所見を見せてこの二つを隠す画面は、答えを見せて代償を隠すことになります。", ["zh"] = "「Redactions」是问题出发前从你身上删去了多少，「left this host」是它究竟有没有离开。若屏幕只展示发现而隐藏这两项，就是展示答案而隐藏代价。", ["hi"] = "«Redactions» यह है कि प्रश्न निकलने से पहले आपका कितना हिस्सा हटाया गया, और «left this host» यह कि वह निकला भी या नहीं। जो स्क्रीन निष्कर्ष दिखाकर ये दोनों छिपाए, वह उत्तर दिखाकर उसकी कीमत छिपा रही होगी।", ["ar"] = "«Redactions» تعني كم أُخذ منك قبل أن يغادر السؤال، و«left this host» تعني هل غادر أصلًا. الشاشة التي تعرض النتائج وتخفي هذين تعرض الجواب وتخفي ثمنه." },
        ["rch.wrist.visits"] = new() { ["en"] = "{n} community visits recorded — JIM points at QRME's rooms, QRME hosts them.", ["es"] = "{n} visitas comunitarias registradas — JIM apunta a las salas de QRME, QRME las aloja.", ["fr"] = "{n} visites communautaires enregistrées — JIM pointe vers les salles de QRME, QRME les héberge.", ["de"] = "{n} Community-Besuche verzeichnet — JIM zeigt auf QRMEs Räume, QRME beherbergt sie.", ["pt"] = "{n} visitas comunitárias registadas — o JIM aponta para as salas do QRME, o QRME aloja-as.", ["it"] = "{n} visite alla community registrate — JIM punta alle stanze di QRME, QRME le ospita.", ["ja"] = "コミュニティ訪問{n}件を記録 — JIMはQRMEのルームを指し示し、QRMEがホストします。", ["zh"] = "已记录{n}次社区访问 — JIM指向QRME的房间，由QRME托管。", ["hi"] = "{n} सामुदायिक भेंट दर्ज — JIM QRME के कमरों की ओर इशारा करता है, QRME उन्हें होस्ट करता है।", ["ar"] = "سُجلت {n} زيارة مجتمعية — يشير JIM إلى غرف QRME، وQRME يستضيفها." },
        ["feed.title"] = new() { ["en"] = "Feed", ["es"] = "Muro", ["fr"] = "Fil", ["de"] = "Feed", ["pt"] = "Fluxo", ["it"] = "Flusso", ["ja"] = "フィード", ["zh"] = "动态", ["hi"] = "फ़ीड", ["ar"] = "التدفّق" },
        ["feed.cannotpost"] = new() { ["en"] = "You cannot post from JIM. Publishing happens in QRME, under your own QRME identity.", ["es"] = "No puedes publicar desde JIM. Publicar ocurre en QRME, con tu propia identidad de QRME.", ["fr"] = "Vous ne pouvez pas publier depuis JIM. La publication se fait dans QRME, sous votre propre identité QRME.", ["de"] = "Aus JIM heraus kann nichts veröffentlicht werden. Das Veröffentlichen geschieht in QRME, unter Ihrer eigenen QRME-Identität.", ["pt"] = "Não podes publicar a partir do JIM. Publicar acontece no QRME, com a tua própria identidade QRME.", ["it"] = "Da JIM non si pubblica. La pubblicazione avviene in QRME, con la tua identità QRME.", ["ja"] = "JIM からは投稿できません。投稿は QRME で、あなた自身の QRME の身元で行います。", ["zh"] = "不能从 JIM 发布。发布发生在 QRME，用你自己的 QRME 身份。", ["hi"] = "आप JIM से पोस्ट नहीं कर सकते। प्रकाशन QRME में होता है, आपकी अपनी QRME पहचान से।", ["ar"] = "لا يمكنك النشر من JIM. النشر يجري في QRME، بهويتك الخاصة هناك." },
        ["feed.openinqrme"] = new() { ["en"] = "Open it in QRME", ["es"] = "Abrirlo en QRME", ["fr"] = "L'ouvrir dans QRME", ["de"] = "In QRME öffnen", ["pt"] = "Abrir no QRME", ["it"] = "Aprirlo in QRME", ["ja"] = "QRME で開く", ["zh"] = "在 QRME 中打开", ["hi"] = "QRME में खोलें", ["ar"] = "افتحه في QRME" },
