        ["sfy.beacons"] = new() { ["en"] = "Beacons", ["es"] = "Balizas", ["fr"] = "Balises", ["de"] = "Baken", ["pt"] = "Balizas", ["it"] = "Beacon", ["ja"] = "ビーコン", ["zh"] = "信标", ["hi"] = "बीकन", ["ar"] = "المنارات" },
        ["sfy.beacons.bystander"] = new() { ["en"] = "A beacon is the bystander's path — for somebody who finds you; SOS is your own.", ["es"] = "Una baliza es el camino del transeúnte — para quien te encuentre; SOS es el tuyo.", ["fr"] = "Une balise est la voie du passant — pour la personne qui vous trouve ; SOS est la vôtre.", ["de"] = "Ein Beacon ist der Weg für Umstehende — für jemanden, der dich findet; SOS ist deiner.", ["pt"] = "Um farol é o caminho de quem passa — para quem te encontrar; SOS é o teu.", ["it"] = "Un beacon è la via del passante — per chi ti trova; SOS è la tua.", ["ja"] = "ビーコンは通りがかりの人のための道です — あなたを見つけた誰かのために。SOSはあなた自身の入口です。", ["zh"] = "信标是旁人的通道 — 供发现你的人使用；SOS 才是你自己的。", ["hi"] = "बीकन राहगीर का रास्ता है — जो आपको पाए उसके लिए; SOS आपका अपना है।", ["ar"] = "المنارة طريق المارّ — لمن يجدك؛ أما SOS فهو بابك أنت." },
        ["sfy.beacons.pitch"] = new() { ["en"] = "A sticker someone can scan to reach help on your behalf. The scanner needs no account and sees only what you chose to put on the card.", ["es"] = "Una pegatina que alguien puede escanear para pedir ayuda en tu nombre. Quien escanea no necesita cuenta y solo ve lo que decidiste poner en la tarjeta.", ["fr"] = "Un autocollant que quelqu'un peut scanner pour appeler de l'aide en votre nom. Le scanneur n'a besoin d'aucun compte et ne voit que ce que vous avez choisi de mettre sur la carte.", ["de"] = "Ein Aufkleber, den jemand scannen kann, um in Ihrem Namen Hilfe zu holen. Wer scannt, braucht kein Konto und sieht nur, was Sie auf die Karte setzen wollten.", ["pt"] = "Um autocolante que alguém pode digitalizar para pedir ajuda em seu nome. Quem digitaliza não precisa de conta e vê apenas o que escolheu pôr no cartão.", ["it"] = "Un adesivo che qualcuno può scansionare per chiedere aiuto per te. Chi scansiona non ha bisogno di account e vede solo ciò che hai scelto di mettere sulla scheda.", ["ja"] = "誰かがスキャンして、あなたに代わって助けを呼べるステッカーです。スキャンする人にアカウントは要らず、見えるのはあなたがカードに載せると決めたものだけです。", ["zh"] = "一张贴纸，别人扫一下就能代你求助。扫描者无需账户，只能看到你选择放上卡片的内容。", ["hi"] = "एक स्टिकर जिसे कोई स्कैन करके आपकी ओर से मदद बुला सके। स्कैन करने वाले को खाता नहीं चाहिए और उसे केवल वही दिखता है जो आपने कार्ड पर रखना चुना।", ["ar"] = "ملصق يمكن لأحد مسحه ليطلب النجدة نيابة عنك. الماسح لا يحتاج حسابًا ولا يرى إلا ما اخترت وضعه على البطاقة." },
        ["sfy.beacons.label.ph"] = new() { ["en"] = "Label (Front door)", ["es"] = "Etiqueta (Puerta principal)", ["fr"] = "Étiquette (Porte d'entrée)", ["de"] = "Beschriftung (Haustür)", ["pt"] = "Etiqueta (Porta da frente)", ["it"] = "Etichetta (Porta d'ingresso)", ["ja"] = "ラベル（玄関）", ["zh"] = "标签（前门）", ["hi"] = "लेबल (मुख्य द्वार)", ["ar"] = "التسمية (الباب الأمامي)" },
