        ["aim.budget.none"] = new() { ["en"] = "No limits set. Financial stress is one of the eight conditions JIM will take on, and a budget is how it learns the shape of yours.", ["es"] = "Sin límites. El estrés financiero es una de las ocho condiciones que JIM atiende, y un presupuesto es como aprende la forma del tuyo.", ["fr"] = "Aucune limite. Le stress financier est l'une des huit situations dont JIM se charge, et un budget est la façon dont il apprend la forme du vôtre.", ["de"] = "Keine Grenzen gesetzt. Finanzieller Stress ist einer der acht Zustände, die JIM übernimmt, und ein Budget ist, wie es die Gestalt Ihres eigenen lernt.", ["pt"] = "Sem limites definidos. O stress financeiro é uma das oito condições que o JIM assume, e um orçamento é como aprende a forma do seu.", ["it"] = "Nessun limite impostato. Lo stress finanziario è una delle otto condizioni di cui JIM si occupa, e un budget è il modo in cui impara la forma del tuo.", ["ja"] = "上限は未設定です。経済的ストレスはJIMが引き受ける八つの状態のひとつで、予算はあなたのそれの形を学ぶ手がかりです。", ["zh"] = "尚未设定上限。财务压力是 JIM 会承接的八种状况之一，而预算正是它了解你这方面轮廓的途径。", ["hi"] = "कोई सीमा तय नहीं। आर्थिक तनाव उन आठ स्थितियों में से एक है जिन्हें JIM संभालता है, और बजट ही वह तरीक़ा है जिससे वह आपकी स्थिति का आकार समझता है।", ["ar"] = "لا حدود محددة. الضغط المالي أحد الحالات الثماني التي يتولاها JIM، والميزانية هي كيف يتعلم شكل حالتك." },
        ["aim.budget.remove"] = new() { ["en"] = "Remove", ["es"] = "Quitar", ["fr"] = "Retirer", ["de"] = "Entfernen", ["pt"] = "Remover", ["it"] = "Rimuovi", ["ja"] = "削除", ["zh"] = "移除", ["hi"] = "हटाएँ", ["ar"] = "أزل" },
        ["aim.budget.set"] = new() { ["en"] = "Set a limit", ["es"] = "Poner un límite", ["fr"] = "Fixer une limite", ["de"] = "Grenze setzen", ["pt"] = "Definir um limite", ["it"] = "Imposta un limite", ["ja"] = "上限を設定", ["zh"] = "设定上限", ["hi"] = "सीमा तय करें", ["ar"] = "حدد سقفًا" },
