        ["hld.plan.canread"] = new() { ["en"] = "Can read it: {list}", ["es"] = "Pueden leerlo: {list}", ["fr"] = "Peuvent le lire : {list}", ["de"] = "Dürfen es lesen: {list}", ["pt"] = "Podem lê-lo: {list}", ["it"] = "Possono leggerlo: {list}", ["ja"] = "読める者: {list}", ["zh"] = "可读取者: {list}", ["hi"] = "इसे पढ़ सकते हैं: {list}", ["ar"] = "يمكنهم قراءته: {list}" },
        ["hld.log"] = new() { ["en"] = "Who has read your record", ["es"] = "Quién ha leído tu registro", ["fr"] = "Qui a lu votre dossier", ["de"] = "Wer Ihre Akte gelesen hat", ["pt"] = "Quem leu o seu registo", ["it"] = "Chi ha letto il tuo registro", ["ja"] = "あなたの記録を読んだ人", ["zh"] = "谁读过你的记录", ["hi"] = "आपका रिकॉर्ड किसने पढ़ा", ["ar"] = "من قرأ سجلك" },
        ["hld.log.empty"] = new() { ["en"] = "The list below is empty because nothing is being recorded — not because nobody has looked. Those are different facts and this screen will not let them look the same.", ["es"] = "La lista de abajo está vacía porque no se está registrando nada — no porque nadie haya mirado. Son hechos distintos y esta pantalla no dejará que parezcan iguales.", ["fr"] = "La liste ci-dessous est vide parce que rien n'est enregistré — pas parce que personne n'a regardé. Ce sont deux faits différents et cet écran ne les laissera pas se ressembler.", ["de"] = "Die Liste unten ist leer, weil nichts aufgezeichnet wird — nicht, weil niemand hineingesehen hat. Das sind verschiedene Tatsachen, und dieser Bildschirm lässt sie nicht gleich aussehen.", ["pt"] = "A lista abaixo está vazia porque nada está a ser registado — não porque ninguém tenha olhado. São factos diferentes e este ecrã não os deixará parecer iguais.", ["it"] = "L'elenco qui sotto è vuoto perché non si sta registrando nulla — non perché nessuno abbia guardato. Sono fatti diversi e questa schermata non li lascerà sembrare uguali.", ["ja"] = "下のリストが空なのは、誰も見ていないからではなく、何も記録されていないからです。この二つは別の事実であり、この画面は両者を同じに見せません。", ["zh"] = "下面的列表为空，是因为什么都没被记录 — 而不是因为无人查看过。这是两个不同的事实，本屏幕不会让它们看起来一样。", ["hi"] = "नीचे की सूची इसलिए खाली है क्योंकि कुछ दर्ज ही नहीं हो रहा — इसलिए नहीं कि किसी ने देखा नहीं। ये दो अलग तथ्य हैं और यह स्क्रीन इन्हें एक जैसा नहीं दिखने देगी।", ["ar"] = "القائمة أدناه فارغة لأن شيئًا لا يُسجَّل — لا لأن أحدًا لم يطّلع. هاتان حقيقتان مختلفتان، وهذه الشاشة لن تدعهما تبدوان متشابهتين." },
        ["hld.audit"] = new() { ["en"] = "What was done, and whether the record was edited", ["es"] = "Qué se hizo, y si el registro fue editado", ["fr"] = "Ce qui a été fait, et si le registre a été modifié", ["de"] = "Was getan wurde — und ob der Eintrag nachträglich geändert wurde", ["pt"] = "O que foi feito, e se o registo foi editado", ["it"] = "Cosa è stato fatto, e se il registro è stato modificato", ["ja"] = "何が行われたか、そしてその記録が後から書き換えられていないか", ["zh"] = "做了什么，以及记录是否被改动过", ["hi"] = "क्या किया गया, और क्या रिकॉर्ड बाद में बदला गया", ["ar"] = "ما الذي جرى، وهل عُدِّل السجل بعدها" },
        ["hld.audit.intact"] = new() { ["en"] = "The chain is intact: every entry still hashes to the one before it, so nothing here has been edited or removed since it was written.", ["es"] = "La cadena está intacta: cada entrada sigue enlazando por hash con la anterior, así que nada de esto se ha editado ni eliminado desde que se escribió.", ["fr"] = "La chaîne est intacte : chaque entrée hache toujours la précédente, donc rien ici n'a été modifié ni supprimé depuis son écriture.", ["de"] = "Die Kette ist unversehrt: Jeder Eintrag hasht weiterhin auf den vorherigen, es wurde hier also seit dem Schreiben nichts geändert oder entfernt.", ["pt"] = "A cadeia está intacta: cada entrada continua a fazer hash da anterior, portanto nada aqui foi editado ou removido desde que foi escrito.", ["it"] = "La catena è intatta: ogni voce continua a fare l'hash della precedente, quindi qui nulla è stato modificato o rimosso da quando è stato scritto.", ["ja"] = "チェーンは無傷です。各項目が直前の項目のハッシュを保持しており、書かれて以降に編集も削除もされていません。", ["zh"] = "链条完整：每条记录仍与前一条哈希相连，因此这里的内容自写入后未被改动或删除。", ["hi"] = "श्रृंखला अक्षुण्ण है: हर प्रविष्टि अब भी पिछली से हैश द्वारा जुड़ी है, इसलिए लिखे जाने के बाद यहाँ कुछ भी बदला या हटाया नहीं गया।", ["ar"] = "السلسلة سليمة: كل مدخل ما زال يُجزّئ ما قبله، فلم يُعدَّل هنا شيء ولم يُحذف منذ كتابته." },
        ["hld.audit.broken"] = new() { ["en"] = "The chain is broken at entry {seq}. Something was edited or removed after it was written. That is exactly what this record exists to tell you.", ["es"] = "La cadena está rota en la entrada {seq}. Algo se editó o se eliminó después de escribirse. Para decirte precisamente eso existe este registro.", ["fr"] = "La chaîne est rompue à l'entrée {seq}. Quelque chose a été modifié ou supprimé après son écriture. C'est exactement ce que ce registre existe pour vous dire.", ["de"] = "Die Kette ist bei Eintrag {seq} gebrochen. Etwas wurde nach dem Schreiben geändert oder entfernt. Genau dafür gibt es diesen Eintrag.", ["pt"] = "A cadeia está quebrada na entrada {seq}. Algo foi editado ou removido depois de escrito. É exatamente isso que este registo existe para lhe dizer.", ["it"] = "La catena è spezzata alla voce {seq}. Qualcosa è stato modificato o rimosso dopo la scrittura. È esattamente ciò che questo registro esiste per dirti.", ["ja"] = "チェーンは項目 {seq} で切れています。書かれた後に何かが編集または削除されました。この記録はまさにそれを伝えるために存在します。", ["zh"] = "链条在第 {seq} 条处断开。有内容在写入之后被改动或删除。这正是本记录存在的意义。", ["hi"] = "श्रृंखला प्रविष्टि {seq} पर टूटी है। लिखे जाने के बाद कुछ बदला या हटाया गया। यह रिकॉर्ड ठीक यही बताने के लिए है।", ["ar"] = "السلسلة مقطوعة عند المدخل {seq}. عُدِّل شيء أو حُذف بعد كتابته. وهذا بالضبط ما وُجد هذا السجل ليخبرك به." },
        ["hld.audit.none"] = new() { ["en"] = "Nothing has been recorded for you yet. The list below is what would be — an empty log here means nothing happened, not that nothing is watched.", ["es"] = "Todavía no se ha registrado nada tuyo. La lista de abajo es lo que se registraría: un registro vacío aquí significa que no ocurrió nada, no que no se vigile nada.", ["fr"] = "Rien n'a encore été consigné vous concernant. La liste ci-dessous est ce qui le serait — un journal vide ici signifie que rien ne s'est produit, pas que rien n'est surveillé.", ["de"] = "Zu Ihnen wurde noch nichts aufgezeichnet. Die Liste unten zeigt, was aufgezeichnet würde — ein leeres Protokoll heißt hier: nichts ist geschehen, nicht: nichts wird beobachtet.", ["pt"] = "Ainda nada foi registado sobre si. A lista abaixo é o que seria — um registo vazio aqui significa que nada aconteceu, não que nada é vigiado.", ["it"] = "Non è ancora stato registrato nulla su di te. L'elenco qui sotto è ciò che lo sarebbe — un registro vuoto qui significa che non è successo nulla, non che nulla sia sorvegliato.", ["ja"] = "あなたについてはまだ何も記録されていません。下の一覧が記録される対象です。ここが空なのは「何も起きていない」という意味であり、「何も見張っていない」という意味ではありません。", ["zh"] = "尚未记录与你有关的任何事。下面列出的是会被记录的内容 — 此处为空意味着什么都没发生，而不是什么都没被记录。", ["hi"] = "आपके बारे में अभी कुछ भी दर्ज नहीं हुआ है। नीचे की सूची वही है जो दर्ज होती — यहाँ खाली लॉग का अर्थ है कि कुछ हुआ ही नहीं, यह नहीं कि कुछ देखा नहीं जा रहा।", ["ar"] = "لم يُسجَّل عنك شيء بعد. القائمة أدناه هي ما كان سيُسجَّل — والسجل الفارغ هنا يعني أن شيئًا لم يحدث، لا أن شيئًا لا يُراقَب." },
        ["hld.audit.watched"] = new() { ["en"] = "What is recorded here", ["es"] = "Qué se registra aquí", ["fr"] = "Ce qui est consigné ici", ["de"] = "Was hier aufgezeichnet wird", ["pt"] = "O que é registado aqui", ["it"] = "Cosa viene registrato qui", ["ja"] = "ここに記録されること", ["zh"] = "这里会记录什么", ["hi"] = "यहाँ क्या दर्ज होता है", ["ar"] = "ما الذي يُسجَّل هنا" },
        ["hld.log.kept"] = new() { ["en"] = "An access record is being kept:", ["es"] = "Se está llevando un registro de accesos:", ["fr"] = "Un registre des accès est tenu :", ["de"] = "Ein Zugriffsprotokoll wird geführt:", ["pt"] = "Está a ser mantido um registo de acessos:", ["it"] = "Si tiene un registro degli accessi:", ["ja"] = "アクセス記録の保持:", ["zh"] = "正在保留访问记录:", ["hi"] = "पहुँच रिकॉर्ड रखा जा रहा है:", ["ar"] = "يُحتفظ بسجل وصول:" },
        ["hld.log.vaulted"] = new() { ["en"] = "Sealed in a vault:", ["es"] = "Sellado en una bóveda:", ["fr"] = "Scellé dans un coffre :", ["de"] = "In einem Tresor versiegelt:", ["pt"] = "Selado num cofre:", ["it"] = "Sigillato in un caveau:", ["ja"] = "保管庫に封印:", ["zh"] = "已封入保险库:", ["hi"] = "तिजोरी में सील:", ["ar"] = "مختوم في خزنة:" },
        ["hld.where"] = new() { ["en"] = "Where the answers come from", ["es"] = "De dónde vienen las respuestas", ["fr"] = "D'où viennent les réponses", ["de"] = "Woher die Antworten kommen", ["pt"] = "De onde vêm as respostas", ["it"] = "Da dove vengono le risposte", ["ja"] = "答えはどこから来るか", ["zh"] = "答案从哪来", ["hi"] = "उत्तर कहाँ से आते हैं", ["ar"] = "من أين تأتي الإجابات" },
        ["hld.where.cloud"] = new() { ["en"] = "Cloud model: {model} · falls back to {fallback}", ["es"] = "Modelo en la nube: {model} · recurre a {fallback}", ["fr"] = "Modèle cloud : {model} · se rabat sur {fallback}", ["de"] = "Cloud-Modell: {model} · fällt zurück auf {fallback}", ["pt"] = "Modelo na nuvem: {model} · recorre a {fallback}", ["it"] = "Modello cloud: {model} · ripiega su {fallback}", ["ja"] = "クラウドモデル: {model} · 代替は{fallback}", ["zh"] = "云端模型: {model} · 回退到{fallback}", ["hi"] = "क्लाउड मॉडल: {model} · विकल्प {fallback}", ["ar"] = "نموذج سحابي: {model} · يعود إلى {fallback}" },
        ["set.cloud"] = new() { ["en"] = "What you contribute", ["es"] = "Lo que aportas", ["fr"] = "Ce que vous contribuez", ["de"] = "Was Sie beitragen", ["pt"] = "O que contribui", ["it"] = "Cosa contribuisci", ["ja"] = "あなたが提供するもの", ["zh"] = "你贡献了什么", ["hi"] = "आप क्या योगदान देते हैं", ["ar"] = "ما تساهم به" },
