        ["set.loc"] = new() { ["en"] = "Where to look", ["es"] = "Dónde buscar", ["fr"] = "Où chercher", ["de"] = "Wo gesucht wird", ["pt"] = "Onde procurar", ["it"] = "Dove cercare", ["ja"] = "どこを探すか", ["zh"] = "在哪里查找", ["hi"] = "कहाँ देखना है", ["ar"] = "أين يُبحث" },
