        ["ns.gd.ask.ph"] = new() { ["en"] = "What would you like to know?", ["es"] = "¿Qué te gustaría saber?", ["fr"] = "Que voulez-vous savoir ?", ["de"] = "Was möchten Sie wissen?", ["pt"] = "O que gostaria de saber?", ["it"] = "Cosa vorresti sapere?", ["ja"] = "何を知りたいですか？", ["zh"] = "你想知道什么？", ["hi"] = "आप क्या जानना चाहेंगे?", ["ar"] = "ماذا تودّ أن تعرف؟" },
