        ["ns.vs.title"] = new() { ["en"] = "Voice", ["es"] = "Voz", ["fr"] = "Voix", ["de"] = "Stimme", ["pt"] = "Voz", ["it"] = "Voce", ["ja"] = "音声", ["zh"] = "语音", ["hi"] = "आवाज़", ["ar"] = "الصوت" },
        ["ns.vs.pitch"] = new() { ["en"] = "Replies are read aloud in your device's own voice — no account needed. Add an ElevenLabs or OpenAI key for a natural one, and to talk back by microphone.", ["es"] = "Las respuestas se leen en voz alta con la voz propia de tu dispositivo — sin cuenta. Añade una clave de ElevenLabs u OpenAI para una voz natural, y para responder por micrófono.", ["fr"] = "Les réponses sont lues à voix haute avec la voix de votre appareil — aucun compte nécessaire. Ajoutez une clé ElevenLabs ou OpenAI pour une voix naturelle, et pour répondre au micro.", ["de"] = "Antworten werden mit der geräteeigenen Stimme vorgelesen — ohne Konto. Fügen Sie einen ElevenLabs- oder OpenAI-Schlüssel hinzu für eine natürliche Stimme und um per Mikrofon zu antworten.", ["pt"] = "As respostas são lidas em voz alta com a voz do seu dispositivo — sem conta. Adicione uma chave ElevenLabs ou OpenAI para uma voz natural, e para responder por microfone.", ["it"] = "Le risposte sono lette ad alta voce con la voce del tuo dispositivo — nessun account necessario. Aggiungi una chiave ElevenLabs o OpenAI per una voce naturale, e per rispondere al microfono.", ["ja"] = "返答は端末自身の音声で読み上げられます — アカウントは不要です。自然な声とマイクでの応答には、ElevenLabsまたはOpenAIのキーを追加してください。", ["zh"] = "回复会用你设备自带的语音朗读 — 无需账户。添加 ElevenLabs 或 OpenAI 密钥即可获得自然嗓音，并可用麦克风回话。", ["hi"] = "जवाब आपके डिवाइस की अपनी आवाज़ में पढ़े जाते हैं — कोई खाता नहीं चाहिए। प्राकृतिक आवाज़ और माइक से जवाब देने के लिए ElevenLabs या OpenAI कुंजी जोड़ें।", ["ar"] = "تُقرأ الردود بصوت جهازك نفسه — دون حاجة لحساب. أضف مفتاح ElevenLabs أو OpenAI لصوت طبيعي وللرد بالميكروفون." },
        ["ns.vs.through"] = new() { ["en"] = "Speaking through {provider}{env}. Talking back by microphone works too.", ["es"] = "Hablando a través de {provider}{env}. Responder por micrófono también funciona.", ["fr"] = "Parle via {provider}{env}. Répondre au micro fonctionne aussi.", ["de"] = "Spricht über {provider}{env}. Antworten per Mikrofon geht auch.", ["pt"] = "A falar através de {provider}{env}. Responder por microfone também funciona.", ["it"] = "Parla tramite {provider}{env}. Rispondere al microfono funziona anche.", ["ja"] = "{provider}{env}を通じて話します。マイクでの応答も使えます。", ["zh"] = "通过{provider}{env}发声。用麦克风回话同样可用。", ["hi"] = "{provider}{env} के ज़रिए बोल रहा है। माइक से जवाब देना भी चलता है।", ["ar"] = "يتحدث عبر {provider}{env}. والرد بالميكروفون يعمل أيضًا." },
        ["ns.vs.left"] = new() { ["en"] = "{left} of {limit} characters left.", ["es"] = "Quedan {left} de {limit} caracteres.", ["fr"] = "Il reste {left} caractères sur {limit}.", ["de"] = "{left} von {limit} Zeichen übrig.", ["pt"] = "Restam {left} de {limit} caracteres.", ["it"] = "Restano {left} caratteri su {limit}.", ["ja"] = "残り {left} / {limit} 文字。", ["zh"] = "还剩 {left} / {limit} 个字符。", ["hi"] = "{limit} में से {left} अक्षर बचे हैं।", ["ar"] = "بقي {left} من {limit} حرفًا." },
        ["ns.vs.spent"] = new() { ["en"] = "The allowance is spent — everything is read in the device's own voice until it refills.", ["es"] = "La asignación está agotada — todo se lee con la voz propia del dispositivo hasta que se reponga.", ["fr"] = "Le crédit est épuisé — tout est lu avec la voix propre de l'appareil jusqu'à son renouvellement.", ["de"] = "Das Kontingent ist aufgebraucht — bis es sich auffüllt, wird alles mit der eigenen Stimme des Geräts vorgelesen.", ["pt"] = "A quota está esgotada — tudo é lido com a voz do próprio dispositivo até se repor.", ["it"] = "Il credito è esaurito — finché non si ricarica, tutto viene letto con la voce del dispositivo.", ["ja"] = "割り当てを使い切りました — 補充されるまで、すべては端末自身の声で読み上げられます。", ["zh"] = "额度已用尽 — 在恢复之前，一切都用设备自带的声音朗读。", ["hi"] = "कोटा ख़त्म हो चुका है — दोबारा भरने तक सब कुछ डिवाइस की अपनी आवाज़ में पढ़ा जाएगा।", ["ar"] = "نفدت الحصة — يُقرأ كل شيء بصوت الجهاز نفسه إلى أن تتجدد." },
        ["ns.vs.key.is_an_id"] = new() { ["en"] = "That is the key's ID, not the key. The dashboard shows the ID beside every key, and the key itself only once — when you create it. The one you want begins sk_ and is much longer.", ["es"] = "Eso es el ID de la clave, no la clave. El panel muestra el ID junto a cada clave, y la clave misma una sola vez: al crearla. La que necesitas empieza por sk_ y es mucho más larga.", ["fr"] = "C'est l'identifiant de la clé, pas la clé. Le tableau de bord affiche l'identifiant à côté de chaque clé, et la clé elle-même une seule fois, à sa création. Celle qu'il vous faut commence par sk_ et est bien plus longue.", ["de"] = "Das ist die ID des Schlüssels, nicht der Schlüssel. Das Dashboard zeigt die ID neben jedem Schlüssel, den Schlüssel selbst nur einmal — beim Erstellen. Der gesuchte beginnt mit sk_ und ist viel länger.", ["pt"] = "Isso é o ID da chave, não a chave. O painel mostra o ID ao lado de cada chave, e a própria chave apenas uma vez — quando a cria. A que procura começa por sk_ e é bem mais longa.", ["it"] = "Quello è l'ID della chiave, non la chiave. Il pannello mostra l'ID accanto a ogni chiave, e la chiave stessa una sola volta, alla creazione. Quella che ti serve inizia con sk_ ed è molto più lunga.", ["ja"] = "それはキーの ID であって、キーではありません。ダッシュボードは各キーの横に ID を表示し、キー本体は作成時の一度だけ表示します。必要なのは sk_ で始まる、はるかに長いほうです。", ["zh"] = "那是密钥的 ID，不是密钥。控制台在每个密钥旁显示 ID，而密钥本身只在创建时显示一次。你需要的那个以 sk_ 开头，长得多。", ["hi"] = "वह कुंजी की ID है, कुंजी नहीं। डैशबोर्ड हर कुंजी के बगल में ID दिखाता है, और कुंजी स्वयं केवल एक बार — बनाते समय। जो चाहिए वह sk_ से शुरू होती है और कहीं ज़्यादा लंबी है।", ["ar"] = "ذلك مُعرِّف المفتاح، لا المفتاح. تعرض لوحة التحكم المُعرِّف بجانب كل مفتاح، وتُظهر المفتاح ذاته مرة واحدة فقط — عند إنشائه. المطلوب يبدأ بـ sk_ وهو أطول بكثير." },
        ["ns.vs.key.unpaid"] = new() { ["en"] = "The key works — the account behind it has an unpaid invoice. ElevenLabs stops serving until the latest one is settled; the Guardian will use the device's own voice until then.", ["es"] = "La clave funciona — la cuenta que hay detrás tiene una factura sin pagar. ElevenLabs deja de atender hasta que se salde la última; hasta entonces el Guardián usará la voz propia del dispositivo.", ["fr"] = "La clé fonctionne — le compte derrière elle a une facture impayée. ElevenLabs cesse de répondre tant que la dernière n'est pas réglée ; d'ici là le Gardien utilisera la voix propre de l'appareil.", ["de"] = "Der Schlüssel funktioniert — das Konto dahinter hat eine offene Rechnung. ElevenLabs liefert nichts mehr, bis die letzte beglichen ist; bis dahin nutzt der Guardian die eigene Stimme des Geräts.", ["pt"] = "A chave funciona — a conta por trás tem uma fatura por pagar. A ElevenLabs deixa de servir até a última ser liquidada; até lá o Guardião usará a voz do próprio dispositivo.", ["it"] = "La chiave funziona — l'account dietro ha una fattura non pagata. ElevenLabs smette di servire finché l'ultima non è saldata; fino ad allora il Guardiano userà la voce del dispositivo.", ["ja"] = "キーは有効です — その背後のアカウントに未払いの請求があります。ElevenLabs は最新の請求が精算されるまで提供を止めます。それまでガーディアンは端末自身の声を使います。", ["zh"] = "密钥是好的 — 其背后的账户有一张未付账单。在结清最新账单之前 ElevenLabs 会停止服务；在此之前守护者将使用设备自带的声音。", ["hi"] = "कुंजी काम करती है — उसके पीछे के खाते का एक बिल बकाया है। जब तक नवीनतम बिल नहीं चुकता, ElevenLabs सेवा रोक देता है; तब तक गार्जियन डिवाइस की अपनी आवाज़ का उपयोग करेगा।", ["ar"] = "المفتاح يعمل — الحساب خلفه عليه فاتورة غير مسدَّدة. تتوقف ElevenLabs عن الخدمة حتى تُسوَّى الأخيرة؛ وحتى ذلك الحين سيستخدم الحارس صوت الجهاز نفسه." },
        ["ns.vs.key.refused"] = new() { ["en"] = "The service did not accept that key. Paste it again, or create a new key and use the one shown at that moment.", ["es"] = "El servicio no aceptó esa clave. Pégala de nuevo, o crea una clave nueva y usa la que se muestre en ese momento.", ["fr"] = "Le service n'a pas accepté cette clé. Recollez-la, ou créez une nouvelle clé et utilisez celle affichée à ce moment-là.", ["de"] = "Der Dienst hat diesen Schlüssel nicht angenommen. Noch einmal einfügen, oder einen neuen Schlüssel anlegen und den nehmen, der dabei angezeigt wird.", ["pt"] = "O serviço não aceitou essa chave. Cole-a outra vez, ou crie uma chave nova e use a que aparecer nesse momento.", ["it"] = "Il servizio non ha accettato quella chiave. Incollala di nuovo, oppure crea una chiave nuova e usa quella mostrata in quel momento.", ["ja"] = "サービスはそのキーを受け付けませんでした。貼り直すか、新しいキーを作ってそのとき表示されたものを使ってください。", ["zh"] = "服务未接受该密钥。重新粘贴一次，或新建一个密钥并使用创建时显示的那串。", ["hi"] = "सेवा ने वह कुंजी स्वीकार नहीं की। इसे दोबारा चिपकाएँ, या नई कुंजी बनाकर उसी क्षण दिखी हुई कुंजी का उपयोग करें।", ["ar"] = "لم تقبل الخدمة ذلك المفتاح. الصقه من جديد، أو أنشئ مفتاحًا جديدًا واستخدم ما يظهر عندها." },
        ["ns.vs.key.unchecked"] = new() { ["en"] = "Saved, but nothing could be reached to check it — it will be tried the first time the Guardian speaks.", ["es"] = "Guardado, pero no se pudo contactar con nada para comprobarlo: se probará la primera vez que el Guardián hable.", ["fr"] = "Enregistré, mais rien n'a pu être joint pour la vérifier — elle sera essayée la première fois que le Gardien parlera.", ["de"] = "Gespeichert, aber es war nichts erreichbar, um ihn zu prüfen — er wird beim ersten Sprechen des Guardians versucht.", ["pt"] = "Guardado, mas não foi possível contactar nada para a verificar — será testada da primeira vez que o Guardião falar.", ["it"] = "Salvato, ma non è stato possibile raggiungere nulla per verificarla: sarà provata la prima volta che il Guardiano parla.", ["ja"] = "保存しましたが、確認のために接続できる先がありませんでした — 次にガーディアンが話すときに試されます。", ["zh"] = "已保存，但无法连接任何服务来核对 — 守护者第一次开口说话时会试用它。", ["hi"] = "सहेजा गया, पर जाँच के लिए कुछ भी संपर्क में नहीं आया — गार्जियन जब पहली बार बोलेगा तब इसे आज़माया जाएगा।", ["ar"] = "تم الحفظ، لكن تعذّر الوصول إلى أي جهة للتحقق منه — سيُجرَّب أول مرة يتحدث فيها الحارس." },
        ["ns.vs.hear"] = new() { ["en"] = "Hear it", ["es"] = "Escucharla", ["fr"] = "L'écouter", ["de"] = "Anhören", ["pt"] = "Ouvi-la", ["it"] = "Ascoltala", ["ja"] = "聞いてみる", ["zh"] = "听听看", ["hi"] = "सुनें", ["ar"] = "استمع إليه" },
        ["ns.ml.title"] = new() { ["en"] = "Email delivery", ["es"] = "Envío de correo", ["fr"] = "Envoi des e-mails", ["de"] = "E-Mail-Zustellung", ["pt"] = "Envio de email", ["it"] = "Recapito email", ["ja"] = "メール配送", ["zh"] = "邮件投递", ["hi"] = "ईमेल वितरण", ["ar"] = "تسليم البريد" },
        ["ns.ml.none"] = new() { ["en"] = "No mail server configured, so nothing can be emailed — verification messages are written to this app's log and signup on this machine simply goes straight in. Point it at a mail account below to send real verification links. For Gmail, turn on 2-Step Verification and create an App password; paste that here, not your normal password.", ["es"] = "No hay servidor de correo configurado, así que no se puede enviar nada por email — los mensajes de verificación se escriben en el registro de esta app y el alta en esta máquina simplemente entra directa. Apúntalo a una cuenta de correo abajo para enviar enlaces de verificación reales. Para Gmail, activa la verificación en dos pasos y crea una contraseña de aplicación; pega esa aquí, no tu contraseña normal.", ["fr"] = "Aucun serveur de messagerie configuré, donc rien ne peut être envoyé par e-mail — les messages de vérification sont écrits dans le journal de cette appli et l'inscription sur cette machine passe directement. Pointez-le vers un compte de messagerie ci-dessous pour envoyer de vrais liens de vérification. Pour Gmail, activez la validation en deux étapes et créez un mot de passe d'application ; collez celui-ci ici, pas votre mot de passe habituel.", ["de"] = "Kein Mailserver konfiguriert, also kann nichts per E-Mail gesendet werden — Bestätigungsnachrichten landen im Log dieser App, und die Anmeldung auf dieser Maschine geht einfach direkt durch. Richten Sie es unten auf ein Mailkonto, um echte Bestätigungslinks zu senden. Für Gmail: Bestätigung in zwei Schritten einschalten und ein App-Passwort erstellen; fügen Sie dieses hier ein, nicht Ihr normales Passwort.", ["pt"] = "Não há servidor de correio configurado, por isso nada pode ser enviado por email — as mensagens de verificação são escritas no registo desta app e o registo nesta máquina entra diretamente. Aponte-o a uma conta de correio abaixo para enviar links de verificação reais. Para o Gmail, ligue a verificação em duas etapas e crie uma palavra-passe de aplicação; cole essa aqui, não a sua palavra-passe normal.", ["it"] = "Nessun server di posta configurato, quindi non si può inviare nulla per email — i messaggi di verifica finiscono nel log di questa app e l'iscrizione su questa macchina passa direttamente. Puntalo a un account di posta qui sotto per inviare link di verifica veri. Per Gmail, attiva la verifica in due passaggi e crea una password per le app; incolla quella qui, non la tua password normale.", ["ja"] = "メールサーバーが設定されていないため、メールは一切送れません — 確認メッセージはこのアプリのログに書き出され、この端末での登録はそのまま通ります。実際の確認リンクを送るには、下でメールアカウントを指定してください。Gmailの場合は2段階認証を有効にしてアプリパスワードを作成し、通常のパスワードではなくそちらをここに貼り付けてください。", ["zh"] = "未配置邮件服务器，因此无法发送任何邮件 — 验证消息会写入本应用的日志，本机上的注册直接通过。请在下方指向一个邮件账户，以发送真实的验证链接。若用 Gmail，请开启两步验证并创建应用专用密码；把那个粘贴到这里，而不是你的常用密码。", ["hi"] = "कोई मेल सर्वर कॉन्फ़िगर नहीं है, इसलिए ईमेल से कुछ नहीं भेजा जा सकता — सत्यापन संदेश इस ऐप के लॉग में लिखे जाते हैं और इस मशीन पर साइनअप सीधे हो जाता है। असली सत्यापन लिंक भेजने के लिए नीचे किसी मेल खाते की ओर इंगित करें। Gmail के लिए 2-चरणीय सत्यापन चालू करें और ऐप पासवर्ड बनाएँ; वही यहाँ चिपकाएँ, अपना सामान्य पासवर्ड नहीं।", ["ar"] = "لا يوجد خادم بريد مهيأ، فلا يمكن إرسال أي بريد — تُكتب رسائل التحقق في سجل هذا التطبيق ويمر التسجيل على هذه الآلة مباشرة. وجّهه إلى حساب بريد أدناه لإرسال روابط تحقق حقيقية. في Gmail، فعّل التحقق بخطوتين وأنشئ كلمة مرور للتطبيقات؛ والصق تلك هنا لا كلمة مرورك المعتادة." },
        ["ns.ml.smtp"] = new() { ["en"] = "Mail goes out through {host}{env}. New accounts must verify by email.", ["es"] = "El correo sale por {host}{env}. Las cuentas nuevas deben verificarse por email.", ["fr"] = "Le courrier part via {host}{env}. Les nouveaux comptes doivent se vérifier par e-mail.", ["de"] = "Mail geht über {host}{env} hinaus. Neue Konten müssen sich per E-Mail bestätigen.", ["pt"] = "O correio sai por {host}{env}. As contas novas têm de verificar por email.", ["it"] = "La posta esce tramite {host}{env}. I nuovi account devono verificarsi via email.", ["ja"] = "メールは{host}{env}を通じて送信されます。新規アカウントはメールでの確認が必要です。", ["zh"] = "邮件经由{host}{env}发出。新账户须通过邮件验证。", ["hi"] = "मेल {host}{env} के ज़रिए जाता है। नए खातों को ईमेल से सत्यापन करना होगा।", ["ar"] = "يخرج البريد عبر {host}{env}. على الحسابات الجديدة التحقق بالبريد." },
