        ["ns.med.times.note"] = new() { ["en"] = "— comma-separated, 24h", ["es"] = "— separadas por comas, 24 h", ["fr"] = "— séparées par des virgules, format 24 h", ["de"] = "— kommagetrennt, 24 h", ["pt"] = "— separadas por vírgulas, 24 h", ["it"] = "— separati da virgole, 24 h", ["ja"] = "— カンマ区切り、24時間表記", ["zh"] = "— 逗号分隔，24小时制", ["hi"] = "— अल्पविराम से अलग, 24 घंटे", ["ar"] = "— مفصولة بفواصل، بنظام 24 ساعة" },
        ["ns.med.critical"] = new() { ["en"] = "Missing this one is worth a check-in", ["es"] = "Saltarse este merece una consulta", ["fr"] = "Manquer celui-ci mérite qu'on prenne de vos nouvelles", ["de"] = "Dieses zu verpassen ist eine Nachfrage wert", ["pt"] = "Falhar este merece uma verificação", ["it"] = "Saltare questo vale un controllo", ["ja"] = "これを飲み忘れたら声をかけてほしい", ["zh"] = "漏服这一种值得来问一句", ["hi"] = "यह छूटे तो हालचाल पूछना बनता है", ["ar"] = "تفويت هذا يستحق اطمئنانًا" },
        ["ns.vg.title"] = new() { ["en"] = "The vigil", ["es"] = "La vigilia", ["fr"] = "La veille", ["de"] = "Die Wache", ["pt"] = "A vigília", ["it"] = "La veglia", ["ja"] = "見守り", ["zh"] = "守夜", ["hi"] = "पहरा", ["ar"] = "السهر" },
        ["ns.vg.pitch"] = new() { ["en"] = "Every other alarm fires on a reading. This one fires on the absence of readings: name someone, and if nothing is heard from you for longer than the quiet period, they are asked to check on you. Any reading stands it down. It never calls emergency services — it knocks on a door.", ["es"] = "Todas las demás alarmas se disparan por una lectura. Esta se dispara por la ausencia de lecturas: nombra a alguien, y si no se sabe nada de ti durante más tiempo que el periodo de silencio, se le pide que vaya a ver cómo estás. Cualquier lectura la desactiva. Nunca llama a los servicios de emergencia — llama a una puerta.", ["fr"] = "Toutes les autres alertes se déclenchent sur une mesure. Celle-ci se déclenche sur l'absence de mesures : nommez quelqu'un, et si l'on n'a rien de vous plus longtemps que la période de silence, on lui demande de prendre de vos nouvelles. Toute mesure la lève. Elle n'appelle jamais les secours — elle frappe à une porte.", ["de"] = "Jeder andere Alarm löst auf eine Messung hin aus. Dieser löst auf das Ausbleiben von Messungen hin aus: nennen Sie jemanden, und hört man länger als die Stillperiode nichts von Ihnen, wird diese Person gebeten, nach Ihnen zu sehen. Jede Messung stellt ihn zurück. Er ruft nie den Rettungsdienst — er klopft an eine Tür.", ["pt"] = "Todos os outros alarmes disparam com uma leitura. Este dispara com a ausência de leituras: nomeie alguém, e se nada se souber de si por mais tempo do que o período de silêncio, pedem-lhe que veja como está. Qualquer leitura o desativa. Nunca chama os serviços de emergência — bate a uma porta.", ["it"] = "Ogni altro allarme scatta su una lettura. Questo scatta sull'assenza di letture: nomina qualcuno, e se non si sa nulla di te per più del periodo di silenzio, gli si chiede di venire a vedere come stai. Qualsiasi lettura lo rientra. Non chiama mai i soccorsi — bussa a una porta.", ["ja"] = "他のあらゆる警報は測定値によって鳴ります。これは測定値がないことによって鳴ります：誰かを指名しておくと、静穏期間を超えてあなたから何の知らせもない場合、その人に様子を見に行くよう頼まれます。どんな測定値でも解除されます。救急を呼ぶことは決してなく — 扉を叩くだけです。", ["zh"] = "其他所有警报都因某条读数而触发。这一个因读数的缺席而触发：指定一个人，若超过静默期仍未收到你的任何消息，就会请他来看看你。任何读数都会将其解除。它绝不呼叫急救 — 它只是去敲一扇门。", ["hi"] = "बाक़ी हर अलार्म किसी रीडिंग पर बजता है। यह रीडिंग की अनुपस्थिति पर बजता है: किसी का नाम दें, और यदि शांत अवधि से अधिक समय तक आपका कोई हाल न मिले, तो उनसे आपकी ख़बर लेने को कहा जाता है। कोई भी रीडिंग इसे शांत कर देती है। यह कभी आपातकालीन सेवाएँ नहीं बुलाता — यह एक दरवाज़ा खटखटाता है।", ["ar"] = "كل إنذار آخر ينطلق بقراءة. هذا ينطلق بغياب القراءات: سمِّ شخصًا، وإن لم يُسمع عنك شيء أطول من فترة الصمت، يُطلب منه أن يطمئن عليك. وأي قراءة تُعيده. لا يستدعي الطوارئ أبدًا — بل يطرق بابًا." },
        ["ns.vg.tripped"] = new() { ["en"] = "⚠ The vigil has tripped — {name} was asked to check on you{after}.", ["es"] = "⚠ La vigilia se ha disparado — se pidió a {name} que fuera a ver cómo estás{after}.", ["fr"] = "⚠ La veille s'est déclenchée — on a demandé à {name} de prendre de vos nouvelles{after}.", ["de"] = "⚠ Die Wache hat ausgelöst — {name} wurde gebeten, nach Ihnen zu sehen{after}.", ["pt"] = "⚠ A vigília disparou — pediram a {name} que visse como está{after}.", ["it"] = "⚠ La veglia è scattata — è stato chiesto a {name} di venire a vedere come stai{after}.", ["ja"] = "⚠ 見守りが作動しました — {name}にあなたの様子を見るよう依頼しました{after}。", ["zh"] = "⚠ 守夜已触发 — 已请{name}来看看你{after}。", ["hi"] = "⚠ पहरा सक्रिय हुआ — {name} से आपकी ख़बर लेने को कहा गया{after}।", ["ar"] = "⚠ انطلق السهر — طُلب من {name} أن يطمئن عليك{after}." },
