        ["ns.bas.sub"] = new() { ["en"] = "The widths below are yours to set. Narrow one to be told sooner; widen it if a metric of yours naturally wanders.", ["es"] = "Los anchos de abajo los fijas tú. Estrecha uno para enterarte antes; ensánchalo si una métrica tuya vaga por naturaleza.", ["fr"] = "Les largeurs ci-dessous sont à vous. Resserrez-en une pour être prévenu plus tôt ; élargissez-la si une de vos métriques vagabonde naturellement.", ["de"] = "Die Breiten darunter bestimmen Sie. Verengen Sie eine, um früher Bescheid zu bekommen; weiten Sie sie, wenn eine Ihrer Metriken von Natur aus wandert.", ["pt"] = "As larguras abaixo são suas. Estreite uma para saber mais cedo; alargue-a se uma métrica sua vagueia por natureza.", ["it"] = "Le larghezze qui sotto le decidi tu. Restringine una per saperlo prima; allargala se una tua metrica vaga per natura.", ["ja"] = "下の幅はあなたが決めます。早く知りたければ狭く、生まれつき揺れやすい指標なら広く。", ["zh"] = "下面的宽度由你设定。调窄可更早得知；某项指标天生爱漂移就调宽。", ["hi"] = "नीचे की चौड़ाइयाँ आप तय करते हैं। जल्दी जानने के लिए संकरी करें; अगर आपका कोई मीट्रिक स्वभावतः भटकता है तो चौड़ी करें।", ["ar"] = "العروض أدناه أنت من يحددها. ضيّق نطاقًا لتُخبَر أبكر؛ ووسّعه إن كان أحد مقاييسك يتجول بطبيعته." },
