        ["ns.bas.learning"] = new() { ["en"] = "learning — {n} resting readings so far", ["es"] = "aprendiendo — {n} lecturas en reposo hasta ahora", ["fr"] = "apprentissage — {n} mesures au repos pour l'instant", ["de"] = "lernt — bisher {n} Ruhemessungen", ["pt"] = "a aprender — {n} leituras em repouso até agora", ["it"] = "in apprendimento — {n} letture a riposo finora", ["ja"] = "学習中 — これまでの安静時測定{n}件", ["zh"] = "学习中 — 目前{n}条静息读数", ["hi"] = "सीख रहा है — अब तक {n} विश्राम रीडिंग", ["ar"] = "قيد التعلم — {n} قراءات راحة حتى الآن" },
