        ["ns.vg.update"] = new() { ["en"] = "Update the vigil", ["es"] = "Actualizar la vigilia", ["fr"] = "Mettre à jour la veille", ["de"] = "Die Wache aktualisieren", ["pt"] = "Atualizar a vigília", ["it"] = "Aggiorna la veglia", ["ja"] = "見守りを更新する", ["zh"] = "更新守夜", ["hi"] = "पहरा अद्यतन करें", ["ar"] = "تحديث السهر" },
        ["ns.acc.needs.title"] = new() { ["en"] = "Who is expected here", ["es"] = "A quién esperamos aquí", ["fr"] = "Qui est attendu ici", ["de"] = "Wer hier erwartet wird", ["pt"] = "Quem é esperado aqui", ["it"] = "Chi è atteso qui", ["ja"] = "ここに来ることが想定されている人", ["zh"] = "这里期待谁的到来", ["hi"] = "यहाँ किनकी अपेक्षा है", ["ar"] = "من ننتظر هنا" },
        ["ns.acc.needs.blind"] = new() { ["en"] = "Blind and low-vision: every function works by text, images carry descriptions, and the screens use standard controls a screen reader can walk.", ["es"] = "Personas ciegas o con baja visión: cada función opera por texto, las imágenes llevan descripciones y las pantallas usan controles estándar que un lector de pantalla puede recorrer.", ["fr"] = "Personnes aveugles ou malvoyantes : chaque fonction passe par le texte, les images portent des descriptions et les écrans utilisent des contrôles standard qu’un lecteur d’écran peut parcourir.", ["de"] = "Blinde und sehbehinderte Menschen: jede Funktion geht über Text, Bilder tragen Beschreibungen, und die Oberfläche nutzt Standard-Elemente, die ein Screenreader ablaufen kann.", ["pt"] = "Pessoas cegas ou com baixa visão: toda função opera por texto, as imagens têm descrições e as telas usam controles padrão que um leitor de tela consegue percorrer.", ["it"] = "Persone cieche o ipovedenti: ogni funzione passa dal testo, le immagini hanno descrizioni e le schermate usano controlli standard che uno screen reader può percorrere.", ["ja"] = "全盲・弱視の方：すべての機能はテキストで使え、画像には説明が付き、画面はスクリーンリーダーがたどれる標準コントロールでできています。", ["zh"] = "盲人和低视力者：一切功能都可通过文字完成，图像带有描述，界面使用屏幕阅读器可以遍历的标准控件。", ["hi"] = "दृष्टिहीन और कम दृष्टि वाले: हर कार्य पाठ से होता है, चित्रों के साथ विवरण है, और स्क्रीन में मानक नियंत्रण हैं जिन्हें स्क्रीन रीडर पढ़ सकता है।", ["ar"] = "المكفوفون وضعاف البصر: كل وظيفة تعمل بالنص، والصور تحمل أوصافًا، والشاشات تستخدم عناصر قياسية يستطيع قارئ الشاشة تتبعها." },
        ["ns.acc.needs.deaf"] = new() { ["en"] = "Deaf and hard of hearing: nothing here requires sound — voice is always optional, never the only way.", ["es"] = "Personas sordas o con pérdida auditiva: nada aquí requiere sonido; la voz es siempre opcional, nunca el único camino.", ["fr"] = "Personnes sourdes ou malentendantes : rien ici n’exige de son — la voix est toujours facultative, jamais le seul chemin.", ["de"] = "Gehörlose und schwerhörige Menschen: nichts hier verlangt Ton — Sprache ist immer optional, nie der einzige Weg.", ["pt"] = "Pessoas surdas ou com perda auditiva: nada aqui exige som — a voz é sempre opcional, nunca o único caminho.", ["it"] = "Persone sorde o con perdita d’udito: niente qui richiede l’audio — la voce è sempre facoltativa, mai l’unica via.", ["ja"] = "ろう・難聴の方：ここでは音を必要とするものはありません。音声は常に任意で、唯一の手段になることはありません。", ["zh"] = "聋人和听障者：这里没有任何功能依赖声音——语音永远是可选的，绝不是唯一途径。", ["hi"] = "बधिर और कम सुनने वाले: यहाँ किसी चीज़ के लिए ध्वनि आवश्यक नहीं — आवाज़ हमेशा वैकल्पिक है, कभी एकमात्र रास्ता नहीं।", ["ar"] = "الصم وضعاف السمع: لا شيء هنا يتطلب صوتًا — الصوت اختياري دائمًا، وليس الطريق الوحيد أبدًا." },
        ["ns.acc.needs.mute"] = new() { ["en"] = "Mute and nonspeaking: nothing here requires speaking — anywhere a microphone is offered, typing does the same job.", ["es"] = "Personas mudas o que no hablan: nada aquí requiere hablar; donde se ofrece un micrófono, escribir hace el mismo trabajo.", ["fr"] = "Personnes muettes ou non verbales : rien ici n’exige de parler — partout où un micro est proposé, écrire fait le même travail.", ["de"] = "Stumme und nicht sprechende Menschen: nichts hier verlangt Sprechen — überall, wo ein Mikrofon angeboten wird, tut Tippen denselben Dienst.", ["pt"] = "Pessoas mudas ou não falantes: nada aqui exige falar — onde houver microfone, digitar faz o mesmo trabalho.", ["it"] = "Persone mute o non parlanti: niente qui richiede di parlare — ovunque ci sia un microfono, scrivere fa lo stesso lavoro.", ["ja"] = "発話しない方・発話が難しい方：ここでは話すことを必要とするものはありません。マイクがある場所ではどこでも、入力が同じ役割を果たします。", ["zh"] = "失语和不说话的人：这里没有任何功能要求开口——凡是提供麦克风的地方，打字都能完成同样的事。", ["hi"] = "मूक और न बोलने वाले: यहाँ बोलना आवश्यक नहीं — जहाँ भी माइक्रोफ़ोन है, वहाँ टाइप करना वही काम करता है।", ["ar"] = "البُكم ومن لا يتكلمون: لا شيء هنا يتطلب الكلام — أينما وُجد ميكروفون، تقوم الكتابة بالمهمة نفسها." },
        ["ns.acc.needs.motor"] = new() { ["en"] = "Limited mobility, amputation, tremor: every control is a standard element the keyboard alone can reach, and no step in this console is timed.", ["es"] = "Movilidad reducida, amputación, temblor: cada control es un elemento estándar alcanzable solo con el teclado, y ningún paso de esta consola tiene límite de tiempo.", ["fr"] = "Mobilité réduite, amputation, tremblement : chaque contrôle est un élément standard atteignable au clavier seul, et aucune étape de cette console n’est chronométrée.", ["de"] = "Eingeschränkte Mobilität, Amputation, Tremor: jedes Element ist ein Standard-Element, das die Tastatur allein erreicht, und kein Schritt in dieser Konsole hat ein Zeitlimit.", ["pt"] = "Mobilidade reduzida, amputação, tremor: todo controle é um elemento padrão alcançável só pelo teclado, e nenhum passo neste console é cronometrado.", ["it"] = "Mobilità ridotta, amputazione, tremore: ogni controllo è un elemento standard raggiungibile con la sola tastiera, e nessun passaggio in questa console è a tempo.", ["ja"] = "運動機能の制約・切断・振戦のある方：すべてのコントロールはキーボードだけで届く標準要素で、このコンソールに制限時間のある操作はありません。", ["zh"] = "行动不便、截肢、震颤者：每个控件都是仅用键盘即可到达的标准元素，本控制台没有任何限时步骤。", ["hi"] = "सीमित गतिशीलता, अंग-विच्छेद, कंपन: हर नियंत्रण एक मानक तत्व है जिस तक केवल कीबोर्ड से पहुँचा जा सकता है, और इस कंसोल में कोई चरण समयबद्ध नहीं है।", ["ar"] = "محدودية الحركة والبتر والرُعاش: كل عنصر تحكم قياسي تصل إليه لوحة المفاتيح وحدها، ولا خطوة في هذه الواجهة مقيدة بوقت." },
        ["ns.acc.needs.cognitive"] = new() { ["en"] = "Autistic and cognitively different people: plain words, one step at a time, nothing flashes, and asking again is always free.", ["es"] = "Personas autistas y cognitivamente diversas: palabras llanas, un paso a la vez, nada parpadea, y volver a preguntar es siempre gratis.", ["fr"] = "Personnes autistes et cognitivement différentes : des mots simples, une étape à la fois, rien ne clignote, et redemander est toujours gratuit.", ["de"] = "Autistische und kognitiv verschiedene Menschen: einfache Worte, ein Schritt nach dem anderen, nichts blinkt, und noch einmal fragen kostet nie etwas.", ["pt"] = "Pessoas autistas e cognitivamente diversas: palavras simples, um passo de cada vez, nada pisca, e perguntar de novo é sempre grátis.", ["it"] = "Persone autistiche e cognitivamente diverse: parole semplici, un passo alla volta, niente lampeggia, e chiedere di nuovo non costa mai nulla.", ["ja"] = "自閉スペクトラムの方・認知の仕方が異なる方：平易な言葉、一度にひとつの手順、点滅するものはなく、もう一度尋ねることはいつでも自由です。", ["zh"] = "自闭症和认知方式不同的人：语言平实，一次一步，没有闪烁的内容，再问一遍永远无妨。", ["hi"] = "ऑटिस्टिक और संज्ञानात्मक रूप से भिन्न लोग: सरल शब्द, एक समय में एक कदम, कुछ नहीं चमकता, और दोबारा पूछना हमेशा निःशुल्क है।", ["ar"] = "المصابون بالتوحد والمختلفون إدراكيًا: كلمات بسيطة، خطوة واحدة في كل مرة، لا شيء يومض، والسؤال مرة أخرى مجاني دائمًا." },
        ["ns.acc.needs.dyslexia"] = new() { ["en"] = "Dyslexia and reading differences: short sentences, real headings, and nothing that punishes rereading.", ["es"] = "Dislexia y diferencias de lectura: frases cortas, encabezados reales y nada que castigue releer.", ["fr"] = "Dyslexie et différences de lecture : phrases courtes, vrais titres, et rien qui punisse la relecture.", ["de"] = "Dyslexie und Leseunterschiede: kurze Sätze, echte Überschriften, und nichts bestraft erneutes Lesen.", ["pt"] = "Dislexia e diferenças de leitura: frases curtas, títulos de verdade e nada que puna reler.", ["it"] = "Dislessia e differenze di lettura: frasi brevi, titoli veri e niente che punisca il rileggere.", ["ja"] = "ディスレクシア・読み方の異なる方：短い文、本物の見出し、読み返しても不利にならない画面。", ["zh"] = "阅读障碍者：短句、真实的标题，重读不会受到任何惩罚。", ["hi"] = "डिस्लेक्सिया और पढ़ने की भिन्नताएँ: छोटे वाक्य, वास्तविक शीर्षक, और दोबारा पढ़ने पर कोई दंड नहीं।", ["ar"] = "عسر القراءة وفروق القراءة: جمل قصيرة وعناوين حقيقية ولا شيء يعاقب على إعادة القراءة." },
        ["ns.acc.needs.motion"] = new() { ["en"] = "Motion sensitivity: when your device asks for reduced motion, this console stops animating.", ["es"] = "Sensibilidad al movimiento: cuando tu dispositivo pide movimiento reducido, esta consola deja de animar.", ["fr"] = "Sensibilité au mouvement : quand votre appareil demande une animation réduite, cette console cesse d’animer.", ["de"] = "Bewegungsempfindlichkeit: wenn dein Gerät reduzierte Bewegung verlangt, hört diese Konsole auf zu animieren.", ["pt"] = "Sensibilidade a movimento: quando seu dispositivo pede movimento reduzido, este console para de animar.", ["it"] = "Sensibilità al movimento: quando il tuo dispositivo chiede movimento ridotto, questa console smette di animare.", ["ja"] = "動きに敏感な方：端末が「視差効果を減らす」を求めると、このコンソールはアニメーションを止めます。", ["zh"] = "对动态敏感者：当你的设备要求减少动态效果时，本控制台会停止动画。", ["hi"] = "गति के प्रति संवेदनशीलता: जब आपका उपकरण कम गति माँगता है, यह कंसोल एनिमेशन बंद कर देता है।", ["ar"] = "الحساسية للحركة: عندما يطلب جهازك تقليل الحركة، تتوقف هذه الواجهة عن التحريك." },
        ["ns.acc.needs.more"] = new() { ["en"] = "Not on this list? The gap is in the list, not in you. Name it below and it becomes our work.", ["es"] = "¿No estás en esta lista? El vacío está en la lista, no en ti. Nómbralo abajo y se convierte en nuestro trabajo.", ["fr"] = "Pas sur cette liste ? Le manque est dans la liste, pas en vous. Nommez-le ci-dessous et cela devient notre travail.", ["de"] = "Nicht auf dieser Liste? Die Lücke ist in der Liste, nicht in dir. Benenne sie unten, und sie wird unsere Arbeit.", ["pt"] = "Não está nesta lista? A lacuna está na lista, não em você. Nomeie-a abaixo e ela vira nosso trabalho.", ["it"] = "Non sei in questa lista? La lacuna è nella lista, non in te. Nominala qui sotto e diventa il nostro lavoro.", ["ja"] = "この一覧にありませんか？足りないのは一覧であって、あなたではありません。下で名前を付けてください。それが私たちの仕事になります。", ["zh"] = "不在这份清单上？缺的是清单，不是你。在下方写出来，它就成为我们的工作。", ["hi"] = "इस सूची में नहीं हैं? कमी सूची में है, आप में नहीं। नीचे उसे नाम दें और वह हमारा काम बन जाएगा।", ["ar"] = "لست في هذه القائمة؟ النقص في القائمة لا فيك. اذكره أدناه وسيصبح عملنا." },
        ["ns.acc.doing.ph"] = new() { ["en"] = "What were you trying to do?", ["es"] = "¿Qué intentabas hacer?", ["fr"] = "Qu’essayiez-vous de faire ?", ["de"] = "Was hast du versucht zu tun?", ["pt"] = "O que você estava tentando fazer?", ["it"] = "Cosa stavi cercando di fare?", ["ja"] = "何をしようとしていましたか？", ["zh"] = "你当时想做什么？", ["hi"] = "आप क्या करने की कोशिश कर रहे थे?", ["ar"] = "ما الذي كنت تحاول فعله؟" },
        ["ns.acc.wall.ph"] = new() { ["en"] = "What stood in the way?", ["es"] = "¿Qué se interpuso?", ["fr"] = "Qu’est-ce qui a fait obstacle ?", ["de"] = "Was stand im Weg?", ["pt"] = "O que ficou no caminho?", ["it"] = "Cosa ti ha ostacolato?", ["ja"] = "何が妨げになりましたか？", ["zh"] = "是什么挡住了你？", ["hi"] = "क्या आड़े आया?", ["ar"] = "ما الذي وقف في الطريق؟" },
        ["ns.acc.help.ph"] = new() { ["en"] = "What would help? (optional)", ["es"] = "¿Qué ayudaría? (opcional)", ["fr"] = "Qu’est-ce qui aiderait ? (facultatif)", ["de"] = "Was würde helfen? (optional)", ["pt"] = "O que ajudaria? (opcional)", ["it"] = "Cosa aiuterebbe? (facoltativo)", ["ja"] = "何があれば助かりますか？（任意）", ["zh"] = "什么会有帮助？（可选）", ["hi"] = "क्या मदद करेगा? (वैकल्पिक)", ["ar"] = "ما الذي قد يساعد؟ (اختياري)" },
        ["ns.acc.send"] = new() { ["en"] = "Send report", ["es"] = "Enviar informe", ["fr"] = "Envoyer le signalement", ["de"] = "Bericht senden", ["pt"] = "Enviar relato", ["it"] = "Invia la segnalazione", ["ja"] = "報告を送る", ["zh"] = "发送报告", ["hi"] = "रिपोर्ट भेजें", ["ar"] = "أرسل البلاغ" },
        ["ns.acc.sent"] = new() { ["en"] = "Received — thank you.", ["es"] = "Recibido. Gracias.", ["fr"] = "Reçu — merci.", ["de"] = "Angekommen — danke.", ["pt"] = "Recebido — obrigado.", ["it"] = "Ricevuto — grazie.", ["ja"] = "受け取りました。ありがとうございます。", ["zh"] = "已收到——谢谢。", ["hi"] = "प्राप्त हुआ — धन्यवाद।", ["ar"] = "وصل البلاغ — شكرًا لك." },
        ["ns.acc.token.ph"] = new() { ["en"] = "Reviewer token", ["es"] = "Token de revisor", ["fr"] = "Jeton de réviseur", ["de"] = "Prüfer-Token", ["pt"] = "Token de revisor", ["it"] = "Token del revisore", ["ja"] = "レビュアートークン", ["zh"] = "审阅者令牌", ["hi"] = "समीक्षक टोकन", ["ar"] = "رمز المراجع" },
        ["ns.acc.load"] = new() { ["en"] = "Load reports", ["es"] = "Cargar informes", ["fr"] = "Charger les signalements", ["de"] = "Berichte laden", ["pt"] = "Carregar relatos", ["it"] = "Carica le segnalazioni", ["ja"] = "報告を読み込む", ["zh"] = "载入报告", ["hi"] = "रिपोर्टें लोड करें", ["ar"] = "حمّل البلاغات" },
        ["ns.acc.none"] = new() { ["en"] = "No reports yet.", ["es"] = "Aún no hay informes.", ["fr"] = "Aucun signalement pour l’instant.", ["de"] = "Noch keine Berichte.", ["pt"] = "Ainda não há relatos.", ["it"] = "Ancora nessuna segnalazione.", ["ja"] = "まだ報告はありません。", ["zh"] = "还没有报告。", ["hi"] = "अभी कोई रिपोर्ट नहीं।", ["ar"] = "لا بلاغات بعد." },
        ["set.invite"] = new() { ["en"] = "Invite key", ["es"] = "Clave de invitación", ["fr"] = "Clé d’invitation", ["de"] = "Einladungsschlüssel", ["pt"] = "Chave de convite", ["it"] = "Chiave di invito", ["ja"] = "招待キー", ["zh"] = "邀请密钥", ["hi"] = "आमंत्रण कुंजी", ["ar"] = "مفتاح الدعوة" },
        ["set.invite.lead"] = new() { ["en"] = "This deployment requires an invite key to create an account — the person who runs it can give you one.", ["es"] = "Esta instalación requiere una clave de invitación para crear una cuenta; quien la administra puede dártela.", ["fr"] = "Cette installation exige une clé d’invitation pour créer un compte — la personne qui la gère peut vous en fournir une.", ["de"] = "Diese Installation verlangt zum Erstellen eines Kontos einen Einladungsschlüssel — die betreibende Person kann ihn dir geben.", ["pt"] = "Esta instalação exige uma chave de convite para criar uma conta — quem a administra pode fornecê-la.", ["it"] = "Questa installazione richiede una chiave di invito per creare un account: chi la gestisce può fornirtela.", ["ja"] = "この環境でアカウントを作成するには招待キーが必要です。運営者から受け取ってください。", ["zh"] = "此部署需要邀请密钥才能创建账户——请向运营者索取。", ["hi"] = "इस परिनियोजन में खाता बनाने के लिए आमंत्रण कुंजी आवश्यक है — इसे चलाने वाला व्यक्ति आपको दे सकता है।", ["ar"] = "يتطلب هذا النشر مفتاح دعوة لإنشاء حساب — يمكن لمن يديره أن يعطيك إياه." },
        ["set.key"] = new() { ["en"] = "Your model API key", ["es"] = "Tu clave de API del modelo", ["fr"] = "Votre clé d'API du modèle", ["de"] = "Ihr Modell-API-Schlüssel", ["pt"] = "A sua chave de API do modelo", ["it"] = "La tua chiave API del modello", ["ja"] = "あなたのモデルAPIキー", ["zh"] = "你的模型 API 密钥", ["hi"] = "आपकी मॉडल API कुंजी", ["ar"] = "مفتاح واجهة النموذج الخاص بك" },
        ["set.key.pitch"] = new() { ["en"] = "Paste your own key (Anthropic sk-ant-…, or OpenAI / xAI / Gemini for those providers) and your Guardian's replies run on your credential. It stays on this device and rides only your own requests — the server never stores it. Leave it empty to use whatever key the deployment lends.", ["es"] = "Pega tu propia clave (Anthropic sk-ant-…, o de OpenAI / xAI / Gemini para esos proveedores) y las respuestas de tu Guardián correrán con tu credencial. Se queda en este dispositivo y viaja solo con tus propias peticiones — el servidor nunca la almacena. Déjala vacía para usar la clave que preste el despliegue.", ["fr"] = "Collez votre propre clé (Anthropic sk-ant-…, ou OpenAI / xAI / Gemini pour ces fournisseurs) et les réponses de votre Gardien tournent sur votre identifiant. Elle reste sur cet appareil et n'accompagne que vos propres requêtes — le serveur ne la stocke jamais. Laissez-la vide pour utiliser la clé que prête le déploiement.", ["de"] = "Fügen Sie Ihren eigenen Schlüssel ein (Anthropic sk-ant-…, oder OpenAI / xAI / Gemini für diese Anbieter), und die Antworten Ihres Guardians laufen auf Ihrem Zugang. Er bleibt auf diesem Gerät und reist nur mit Ihren eigenen Anfragen — der Server speichert ihn nie. Lassen Sie ihn leer, um den Schlüssel zu nutzen, den das Deployment leiht.", ["pt"] = "Cole a sua própria chave (Anthropic sk-ant-…, ou OpenAI / xAI / Gemini para esses fornecedores) e as respostas do seu Guardião correm com a sua credencial. Fica neste dispositivo e viaja só com os seus próprios pedidos — o servidor nunca a guarda. Deixe-a vazia para usar a chave que o deployment empresta.", ["it"] = "Incolla la tua chiave (Anthropic sk-ant-…, oppure OpenAI / xAI / Gemini per quei provider) e le risposte del tuo Guardian girano sulla tua credenziale. Resta su questo dispositivo e viaggia solo con le tue richieste — il server non la memorizza mai. Lasciala vuota per usare la chiave che presta il deployment.", ["ja"] = "自分のキーを貼り付けてください（Anthropicは sk-ant-…、各プロバイダーはOpenAI / xAI / Gemini のもの）。するとガーディアンの返答はあなたの資格情報で動きます。キーはこの端末に留まり、あなた自身のリクエストにだけ同行します — サーバーが保存することはありません。空欄にすれば、この配備が貸すキーが使われます。", ["zh"] = "粘贴你自己的密钥（Anthropic 用 sk-ant-…，对应提供方则用 OpenAI / xAI / Gemini 的密钥），你的守护者的回复便以你的凭证运行。它留在本设备上，只随你自己的请求同行 — 服务器绝不存储它。留空则使用本部署出借的密钥。", ["hi"] = "अपनी कुंजी चिपकाएँ (Anthropic के लिए sk-ant-…, या उन प्रदाताओं के लिए OpenAI / xAI / Gemini) और आपके गार्जियन के जवाब आपकी क्रेडेंशियल पर चलेंगे। यह इसी डिवाइस पर रहती है और केवल आपके अपने अनुरोधों के साथ जाती है — सर्वर इसे कभी संग्रहित नहीं करता। खाली छोड़ें तो डिप्लॉयमेंट जो कुंजी उधार देता है वही चलेगी।", ["ar"] = "الصق مفتاحك الخاص (Anthropic بصيغة sk-ant-…، أو OpenAI / xAI / Gemini لتلك المزودات) فتعمل ردود حارسك على اعتمادك. يبقى على هذا الجهاز ويرافق طلباتك أنت فقط — ولا يخزّنه الخادم أبدًا. اتركه فارغًا لاستخدام المفتاح الذي يعيره هذا النشر." },
        ["set.key.label"] = new() { ["en"] = "API key", ["es"] = "Clave de API", ["fr"] = "Clé d'API", ["de"] = "API-Schlüssel", ["pt"] = "Chave de API", ["it"] = "Chiave API", ["ja"] = "APIキー", ["zh"] = "API 密钥", ["hi"] = "API कुंजी", ["ar"] = "مفتاح الواجهة" },
