        ["ov.language.sub"] = new() { ["en"] = "Everything drafted for you — guidance, coaching, first-aid steps, waiver terms — is delivered in this language.", ["es"] = "Todo lo que se redacta para ti —indicaciones, acompañamiento, primeros auxilios, cláusulas del consentimiento— llega en este idioma.", ["fr"] = "Tout ce qui est rédigé pour vous — conseils, accompagnement, gestes de premiers secours, termes de la renonciation — vous parvient dans cette langue.", ["de"] = "Alles, was für dich verfasst wird — Hinweise, Coaching, Erste-Hilfe-Schritte, Verzichtsklauseln — kommt in dieser Sprache.", ["pt"] = "Tudo o que é redigido para si — orientações, acompanhamento, passos de primeiros socorros, cláusulas do consentimento — chega neste idioma.", ["it"] = "Tutto ciò che viene scritto per te — indicazioni, coaching, gesti di primo soccorso, clausole della liberatoria — arriva in questa lingua.", ["ja"] = "あなたのために書かれるものはすべて——案内、コーチング、応急手当の手順、同意書の文言——この言語で届きます。", ["zh"] = "为你撰写的一切 — 指导、辅导、急救步骤、授权条款 — 都以这种语言呈现。", ["hi"] = "आपके लिए लिखी जाने वाली हर चीज़ — मार्गदर्शन, कोचिंग, प्राथमिक उपचार के चरण, अनुमति-पत्र की शर्तें — इसी भाषा में मिलती है।", ["ar"] = "كل ما يُصاغ لك — الإرشاد والتدريب وخطوات الإسعاف وبنود التنازل — يصلك بهذه اللغة." },
