        ["eng.pitch"] = new() { ["en"] = "The coach answers one turn at a time. This stays open until you sign off, can do things for you while it is open, and lists everything it did so you can take it back.", ["es"] = "El coach responde turno a turno. Esto queda abierto hasta que te despides, puede hacer cosas por ti mientras está abierto y enumera todo lo que hizo para que puedas deshacerlo.", ["fr"] = "Le coach répond un tour à la fois. Ceci reste ouvert jusqu'à ce que vous vous déconnectiez, peut agir pour vous pendant ce temps, et liste tout ce qu'il a fait pour que vous puissiez l'annuler.", ["de"] = "Der Coach antwortet Zug um Zug. Dies bleibt offen, bis Sie sich abmelden, kann in dieser Zeit Dinge für Sie tun und listet alles auf, damit Sie es zurücknehmen können.", ["pt"] = "O coach responde um turno de cada vez. Isto fica aberto até você se despedir, pode fazer coisas por si enquanto está aberto e lista tudo o que fez para poder desfazer.", ["it"] = "Il coach risponde un turno alla volta. Questa resta aperta finché non ti congedi, può fare cose per te mentre è aperta ed elenca tutto ciò che ha fatto perché tu possa annullarlo.", ["ja"] = "コーチは一往復ずつ答えます。こちらはサインオフするまで開いたままで、その間あなたの代わりに操作でき、行ったことをすべて一覧にするので取り消せます。", ["zh"] = "教练一次回答一轮。这个会话在你签退前一直开着，其间可以替你操作，并列出它做过的每一件事，好让你撤回。", ["hi"] = "कोच एक बार में एक बारी जवाब देता है। यह तब तक खुला रहता है जब तक आप साइन ऑफ़ न करें, खुले रहने पर आपके लिए काम कर सकता है, और जो किया वह सब सूचीबद्ध करता है ताकि आप वापस ले सकें।", ["ar"] = "يجيب المدرب دورًا بدور. هذه تبقى مفتوحة حتى تسجّل خروجك، ويمكنها أن تفعل أشياء نيابة عنك ما دامت مفتوحة، وتُدرج كل ما فعلته لتستطيع التراجع عنه." },
        ["eng.permits"] = new() { ["en"] = "What you have let it change", ["es"] = "Lo que le has dejado cambiar", ["fr"] = "Ce que vous l'avez laissé changer", ["de"] = "Was Sie es ändern lassen", ["pt"] = "O que lhe permitiu alterar", ["it"] = "Cosa gli hai lasciato cambiare", ["ja"] = "変更を許していること", ["zh"] = "你允许它改动的部分", ["hi"] = "आपने इसे क्या बदलने दिया है", ["ar"] = "ما سمحتَ له بتغييره" },
        ["eng.permits.note"] = new() { ["en"] = "Tell it out loud what you want on or off and it will do it — for the groups you have switched on here. Each one goes off again the same way.", ["es"] = "Dile en voz alta qué quieres activar o desactivar y lo hará, en los grupos que hayas activado aquí. Cada uno se desactiva igual.", ["fr"] = "Dites-lui à voix haute ce que vous voulez activer ou désactiver et il le fera — pour les groupes que vous avez activés ici. Chacun se désactive de la même façon.", ["de"] = "Sagen Sie laut, was an oder aus sein soll, und es erledigt das — für die Gruppen, die Sie hier eingeschaltet haben. Jede lässt sich genauso wieder ausschalten.", ["pt"] = "Diga em voz alta o que quer ligado ou desligado e ele fá-lo — nos grupos que tiver ligado aqui. Cada um desliga-se da mesma forma.", ["it"] = "Digli ad alta voce cosa vuoi attivo o disattivo e lo farà, per i gruppi che hai attivato qui. Ognuno si disattiva allo stesso modo.", ["ja"] = "何をオンにしたいか、オフにしたいかを声で伝えれば、ここでオンにしたグループについては実行します。同じ手順でいつでもオフにできます。", ["zh"] = "把想开或想关的事情说出来，它就会去做 —— 限于你在这里打开的组。每一组都能用同样的方式关掉。", ["hi"] = "आप जो चालू या बंद करवाना चाहते हैं, बोलकर बता दें और यह कर देगा — उन समूहों के लिए जिन्हें आपने यहाँ चालू किया है। हर एक इसी तरह बंद भी होता है।", ["ar"] = "قل بصوتك ما تريد تشغيله أو إيقافه وسيفعله — في المجموعات التي شغّلتها هنا. وكل واحدة تُطفأ بالطريقة نفسها." },
