        ["eng.reach.note"] = new() { ["en"] = "A written list, not your whole account. Nothing here raises an alarm, moves money, or ends anything — those doors are not on it at all.", ["es"] = "Una lista escrita, no toda tu cuenta. Nada de esto activa una alarma, mueve dinero ni termina nada: esas puertas no están en la lista.", ["fr"] = "Une liste écrite, pas tout votre compte. Rien ici ne déclenche d'alarme, ne déplace d'argent ni ne met fin à quoi que ce soit — ces portes n'y figurent pas.", ["de"] = "Eine geschriebene Liste, nicht Ihr ganzes Konto. Nichts hier löst einen Alarm aus, bewegt Geld oder beendet etwas — diese Türen stehen gar nicht darauf.", ["pt"] = "Uma lista escrita, não a sua conta inteira. Nada aqui dispara um alarme, move dinheiro ou termina o que quer que seja — essas portas nem constam.", ["it"] = "Un elenco scritto, non tutto il tuo account. Niente qui fa scattare un allarme, muove denaro o chiude qualcosa: quelle porte non ci sono affatto.", ["ja"] = "書かれた一覧であって、アカウント全体ではありません。ここには警報を出すもの、お金を動かすもの、何かを終わらせるものは一つもありません — その扉は載っていません。", ["zh"] = "这是一份写下来的清单，不是你的整个账户。这里没有任何一项会触发警报、动用钱款或终止什么——那些门根本不在清单上。", ["hi"] = "यह एक लिखी हुई सूची है, आपका पूरा खाता नहीं। यहाँ कुछ भी अलार्म नहीं बजाता, पैसा नहीं हिलाता, कुछ ख़त्म नहीं करता — वे दरवाज़े इसमें हैं ही नहीं।", ["ar"] = "قائمة مكتوبة، لا حسابك كله. لا شيء هنا يطلق إنذارًا أو يحرّك مالًا أو ينهي شيئًا — تلك الأبواب ليست عليها أصلًا." },
