        ["eng.none"] = new() { ["en"] = "Nobody is engaged", ["es"] = "Nadie está en sesión", ["fr"] = "Personne n'est en session", ["de"] = "Niemand ist verbunden", ["pt"] = "Ninguém está em sessão", ["it"] = "Nessuno è in sessione", ["ja"] = "接続していません", ["zh"] = "当前没有会话", ["hi"] = "कोई जुड़ा नहीं है", ["ar"] = "لا أحد في جلسة" },
        ["eng.none.note"] = new() { ["en"] = "Open one and it stays open — through closing the app, through tomorrow — until you sign off.", ["es"] = "Abre una y se queda abierta — aunque cierres la app, aunque pase el día — hasta que te despidas.", ["fr"] = "Ouvrez-en une et elle reste ouverte — même si vous fermez l'app, même demain — jusqu'à ce que vous vous déconnectiez.", ["de"] = "Öffnen Sie eine, und sie bleibt offen — auch wenn Sie die App schließen, auch morgen — bis Sie sich abmelden.", ["pt"] = "Abra uma e ela fica aberta — mesmo fechando a app, mesmo amanhã — até você se despedir.", ["it"] = "Aprine una e resta aperta — anche chiudendo l'app, anche domani — finché non ti congedi.", ["ja"] = "開けばそのまま — アプリを閉じても、翌日になっても — サインオフするまで開いています。", ["zh"] = "开一个，它就一直开着——关掉应用也好，到了明天也好——直到你签退。", ["hi"] = "एक खोलिए और वह खुला रहेगा — ऐप बंद करने पर भी, कल भी — जब तक आप साइन ऑफ़ न करें।", ["ar"] = "افتح واحدة وتبقى مفتوحة — حتى لو أغلقت التطبيق، وحتى غدًا — إلى أن تسجّل خروجك." },
        ["eng.open"] = new() { ["en"] = "Engage", ["es"] = "Iniciar sesión", ["fr"] = "Engager", ["de"] = "Verbinden", ["pt"] = "Iniciar sessão", ["it"] = "Avvia sessione", ["ja"] = "接続する", ["zh"] = "开始会话", ["hi"] = "जुड़ें", ["ar"] = "ابدأ الجلسة" },
        ["eng.you"] = new() { ["en"] = "You", ["es"] = "Tú", ["fr"] = "Vous", ["de"] = "Sie", ["pt"] = "Você", ["it"] = "Tu", ["ja"] = "あなた", ["zh"] = "你", ["hi"] = "आप", ["ar"] = "أنت" },
        ["eng.jim"] = new() { ["en"] = "JIM", ["es"] = "JIM", ["fr"] = "JIM", ["de"] = "JIM", ["pt"] = "JIM", ["it"] = "JIM", ["ja"] = "JIM", ["zh"] = "JIM", ["hi"] = "JIM", ["ar"] = "JIM" },
        ["eng.say"] = new() { ["en"] = "Send it", ["es"] = "Enviarlo", ["fr"] = "L'envoyer", ["de"] = "Absenden", ["pt"] = "Enviar", ["it"] = "Invialo", ["ja"] = "送信する", ["zh"] = "发送", ["hi"] = "भेजें", ["ar"] = "أرسِلها" },
        ["eng.say.ph"] = new() { ["en"] = "Tell it what you want — it will say what it is about to change before it changes it.", ["es"] = "Dile lo que quieres: dirá qué va a cambiar antes de cambiarlo.", ["fr"] = "Dites-lui ce que vous voulez — il annoncera ce qu'il va changer avant de le changer.", ["de"] = "Sagen Sie, was Sie wollen — es nennt, was es ändern wird, bevor es das tut.", ["pt"] = "Diga o que quer — dirá o que vai mudar antes de mudar.", ["it"] = "Digli che cosa vuoi: dirà che cosa sta per cambiare prima di cambiarlo.", ["ja"] = "望むことを伝えてください。変更する前に、何を変えるつもりかを先に言います。", ["zh"] = "告诉它你想要什么——它会先说要改什么，然后再改。", ["hi"] = "बताइए आप क्या चाहते हैं — बदलने से पहले यह बताएगा कि क्या बदलने जा रहा है।", ["ar"] = "قل له ما تريد — سيقول ما الذي سيغيّره قبل أن يغيّره." },
        ["eng.offline"] = new() { ["en"] = "an engaged session needs the online model — the offline one can answer you, but it cannot do anything for you. Nothing was changed.", ["es"] = "una sesión activa necesita el modelo en línea: el sin conexión puede responderte, pero no puede hacer nada por ti. No se cambió nada.", ["fr"] = "une session engagée a besoin du modèle en ligne — celui hors ligne peut vous répondre, mais il ne peut rien faire pour vous. Rien n'a été modifié.", ["de"] = "eine laufende Sitzung braucht das Online-Modell — das Offline-Modell kann Ihnen antworten, aber nichts für Sie tun. Es wurde nichts geändert.", ["pt"] = "uma sessão em curso precisa do modelo online — o offline pode responder-lhe, mas não pode fazer nada por si. Nada foi alterado.", ["it"] = "una sessione in corso ha bisogno del modello online: quello offline può risponderti, ma non può fare nulla per te. Non è stato cambiato nulla.", ["ja"] = "接続中のセッションにはオンラインのモデルが必要です — オフラインのモデルは答えられますが、あなたの代わりに何かをすることはできません。何も変更されていません。", ["zh"] = "会话中的它需要在线模型——离线的那个可以回答你，但不能替你做事。什么也没有改动。", ["hi"] = "चालू सत्र के लिए ऑनलाइन मॉडल चाहिए — ऑफ़लाइन वाला जवाब दे सकता है, पर आपके लिए कुछ कर नहीं सकता। कुछ भी नहीं बदला।", ["ar"] = "تحتاج الجلسة القائمة إلى النموذج المتصل — أما غير المتصل فيستطيع أن يجيبك، لكنه لا يستطيع أن يفعل شيئًا نيابة عنك. لم يتغيّر شيء." },
        ["eng.trail"] = new() { ["en"] = "What it did", ["es"] = "Lo que hizo", ["fr"] = "Ce qu'il a fait", ["de"] = "Was es getan hat", ["pt"] = "O que fez", ["it"] = "Che cosa ha fatto", ["ja"] = "行ったこと", ["zh"] = "它做了什么", ["hi"] = "इसने क्या किया", ["ar"] = "ما الذي فعله" },
        ["eng.trail.note"] = new() { ["en"] = "Every change, newest first, with the way back beside it.", ["es"] = "Cada cambio, del más reciente al más antiguo, con la vuelta atrás al lado.", ["fr"] = "Chaque changement, du plus récent au plus ancien, avec le retour en arrière à côté.", ["de"] = "Jede Änderung, neueste zuerst, mit dem Weg zurück daneben.", ["pt"] = "Cada mudança, da mais recente para a mais antiga, com a volta atrás ao lado.", ["it"] = "Ogni modifica, dalla più recente, con accanto la via del ritorno.", ["ja"] = "変更のすべてを新しい順に、取り消す手立てを添えて。", ["zh"] = "每一处更改，最新的在前，旁边就是回退的路。", ["hi"] = "हर बदलाव, नया पहले, साथ में वापसी का रास्ता।", ["ar"] = "كل تغيير، الأحدث أولًا، وبجانبه طريق العودة." },
        ["eng.trail.none"] = new() { ["en"] = "It has not changed anything.", ["es"] = "No ha cambiado nada.", ["fr"] = "Il n'a rien changé.", ["de"] = "Es hat nichts geändert.", ["pt"] = "Não mudou nada.", ["it"] = "Non ha cambiato nulla.", ["ja"] = "何も変更していません。", ["zh"] = "它没有改动任何东西。", ["hi"] = "इसने कुछ नहीं बदला।", ["ar"] = "لم يغيّر شيئًا." },
