        ["eng.undone"] = new() { ["en"] = "taken back", ["es"] = "deshecho", ["fr"] = "annulé", ["de"] = "zurückgenommen", ["pt"] = "desfeito", ["it"] = "annullato", ["ja"] = "取り消し済み", ["zh"] = "已撤回", ["hi"] = "वापस लिया", ["ar"] = "تم التراجع" },
        ["eng.off"] = new() { ["en"] = "Sign off", ["es"] = "Despedirse", ["fr"] = "Se déconnecter", ["de"] = "Abmelden", ["pt"] = "Despedir-se", ["it"] = "Congedati", ["ja"] = "サインオフ", ["zh"] = "签退", ["hi"] = "साइन ऑफ़", ["ar"] = "تسجيل الخروج" },
        ["eng.off.note"] = new() { ["en"] = "Signing off does not mean going unwatched. What this session was about goes to the offline coach, and anything you name below it keeps an eye on while you are away.", ["es"] = "Despedirte no significa quedar sin vigilancia. De qué trató esta sesión pasa al coach sin conexión, y lo que nombres abajo lo seguirá vigilando mientras no estés.", ["fr"] = "Se déconnecter ne veut pas dire ne plus être suivi. Ce dont il était question passe au coach hors ligne, et tout ce que vous nommez ci-dessous, il le surveille en votre absence.", ["de"] = "Abmelden heißt nicht unbeobachtet. Worum es in dieser Sitzung ging, geht an den Offline-Coach, und was Sie unten nennen, behält er im Auge, während Sie weg sind.", ["pt"] = "Despedir-se não significa ficar sem vigilância. O tema desta sessão passa para o coach offline, e tudo o que nomear abaixo ele fica a vigiar enquanto está fora.", ["it"] = "Congedarti non significa restare senza qualcuno che guarda. Di che cosa parlava questa sessione passa al coach offline, e quello che scrivi qui sotto lo tiene d'occhio mentre non ci sei.", ["ja"] = "サインオフしても見守られなくなるわけではありません。このセッションの内容はオフラインのコーチに引き継がれ、下に挙げたことは留守のあいだ見ていてくれます。", ["zh"] = "签退不等于无人看顾。这次会话的内容会交给离线教练，你在下面写下的事，它会在你不在时替你留意。", ["hi"] = "साइन ऑफ़ का मतलब बिना निगरानी के रहना नहीं है। यह सत्र किस बारे में था वह ऑफ़लाइन कोच को चला जाता है, और नीचे जो आप लिखेंगे उस पर वह आपकी अनुपस्थिति में नज़र रखेगा।", ["ar"] = "تسجيل الخروج لا يعني أن يُترك أمرك. ما دارت حوله هذه الجلسة ينتقل إلى المدرب دون اتصال، وكل ما تسمّيه أدناه يبقى تحت عينه في غيابك." },
        ["eng.off.ph"] = new() { ["en"] = "One thing per line — in your own words.", ["es"] = "Una cosa por línea, con tus propias palabras.", ["fr"] = "Une chose par ligne, avec vos propres mots.", ["de"] = "Eine Sache pro Zeile — in Ihren eigenen Worten.", ["pt"] = "Uma coisa por linha — nas suas palavras.", ["it"] = "Una cosa per riga, con parole tue.", ["ja"] = "1 行に 1 つ、あなた自身の言葉で。", ["zh"] = "一行一件，用你自己的话。", ["hi"] = "हर पंक्ति में एक बात — अपने ही शब्दों में।", ["ar"] = "شيء واحد في كل سطر — بكلماتك أنت." },
        ["eng.watch"] = new() { ["en"] = "Being watched for", ["es"] = "Bajo vigilancia", ["fr"] = "Sous surveillance", ["de"] = "Wird beobachtet", ["pt"] = "Sob vigilância", ["it"] = "Sotto osservazione", ["ja"] = "見守っていること", ["zh"] = "正在留意", ["hi"] = "जिस पर नज़र है", ["ar"] = "تحت المتابعة" },
        ["eng.watch.note"] = new() { ["en"] = "The offline coach carries these into every answer, and raises them unprompted.", ["es"] = "El coach sin conexión lleva esto a cada respuesta y lo saca sin que se lo pidan.", ["fr"] = "Le coach hors ligne les porte dans chaque réponse et les évoque sans qu'on le lui demande.", ["de"] = "Der Offline-Coach trägt diese in jede Antwort und spricht sie ungefragt an.", ["pt"] = "O coach offline leva isto para cada resposta e traz o assunto sem lhe pedirem.", ["it"] = "Il coach offline se li porta in ogni risposta e li tira fuori senza che glielo si chieda.", ["ja"] = "オフラインのコーチはこれらを毎回の答えに携え、こちらから言わなくても持ち出します。", ["zh"] = "离线教练会把这些带进每一次回答，并会主动提起。", ["hi"] = "ऑफ़लाइन कोच इन्हें हर जवाब में साथ रखता है और बिना पूछे उठाता भी है।", ["ar"] = "يحمل المدرب دون اتصال هذه في كل إجابة، ويطرحها من تلقاء نفسه." },
        ["eng.watch.none"] = new() { ["en"] = "Nothing is on the list.", ["es"] = "No hay nada en la lista.", ["fr"] = "Rien sur la liste.", ["de"] = "Nichts auf der Liste.", ["pt"] = "Nada na lista.", ["it"] = "Non c'è niente in elenco.", ["ja"] = "一覧には何もありません。", ["zh"] = "清单上没有内容。", ["hi"] = "सूची में कुछ नहीं है।", ["ar"] = "لا شيء في القائمة." },
        ["eng.watch.ph"] = new() { ["en"] = "Add something to watch for", ["es"] = "Añade algo que vigilar", ["fr"] = "Ajoutez quelque chose à surveiller", ["de"] = "Etwas zum Beobachten hinzufügen", ["pt"] = "Acrescente algo para vigiar", ["it"] = "Aggiungi qualcosa da tenere d'occhio", ["ja"] = "見守ってほしいことを足す", ["zh"] = "添加一件要留意的事", ["hi"] = "नज़र रखने के लिए कुछ जोड़ें", ["ar"] = "أضف شيئًا لمتابعته" },
        ["eng.watch.stop"] = new() { ["en"] = "Stop watching", ["es"] = "Dejar de vigilar", ["fr"] = "Ne plus surveiller", ["de"] = "Nicht mehr beobachten", ["pt"] = "Deixar de vigiar", ["it"] = "Smetti di osservare", ["ja"] = "見守りをやめる", ["zh"] = "不再留意", ["hi"] = "नज़र रखना बंद करें", ["ar"] = "أوقف المتابعة" },
        ["tab.coach"] = new() { ["en"] = "Coach", ["es"] = "Coach", ["fr"] = "Coach", ["de"] = "Coach", ["pt"] = "Coach", ["it"] = "Coach", ["ja"] = "コーチ", ["zh"] = "教练", ["hi"] = "कोच", ["ar"] = "مدرب" },
        ["alarm.tripped"] = new() { ["en"] = "The crash watch tripped: {name} was contacted. Any normal reading stands it down.", ["es"] = "La vigilancia de caídas se activó: se contactó a {name}. Cualquier lectura normal la desactiva.", ["fr"] = "La veille d'accident s'est déclenchée : {name} a été contacté. Toute mesure normale la désarme.", ["de"] = "Die Sturzwache hat ausgelöst: {name} wurde benachrichtigt. Jeder normale Messwert setzt sie zurück.", ["pt"] = "A vigilância de queda disparou: {name} foi contactado. Qualquer leitura normal desativa-a.", ["it"] = "La sorveglianza incidenti è scattata: {name} è stato contattato. Qualsiasi misurazione normale la disattiva.", ["ja"] = "クラッシュウォッチが作動しました：{name} に連絡しました。通常の測定値が届けば解除されます。", ["zh"] = "跌倒守护已触发：已联系 {name}。任何正常读数都会将其解除。", ["hi"] = "क्रैश वॉच सक्रिय हो गई: {name} से संपर्क किया गया। कोई भी सामान्य रीडिंग इसे बंद कर देती है।", ["ar"] = "تم تفعيل مراقبة الحوادث: جرى الاتصال بـ {name}. وأي قراءة طبيعية تُلغيها." },
        ["alarm.armed"] = new() { ["en"] = "Armed — {name} will be contacted after {n} unanswered attempts.", ["es"] = "Activada — se contactará a {name} tras {n} intentos sin respuesta.", ["fr"] = "Armée — {name} sera contacté après {n} tentatives sans réponse.", ["de"] = "Scharf — {name} wird nach {n} unbeantworteten Versuchen benachrichtigt.", ["pt"] = "Armada — {name} será contactado após {n} tentativas sem resposta.", ["it"] = "Attiva — {name} verrà contattato dopo {n} tentativi senza risposta.", ["ja"] = "作動中 — 応答のない確認が {n} 回続くと {name} に連絡します。", ["zh"] = "已启用 — 在 {n} 次无人应答后将联系 {name}。", ["hi"] = "सक्रिय — {n} बार उत्तर न मिलने पर {name} से संपर्क किया जाएगा।", ["ar"] = "مُفعَّلة — سيجري الاتصال بـ {name} بعد {n} محاولات دون رد." },
        ["alarm.ems"] = new() { ["en"] = "May request emergency services (relayed as a request — this app cannot itself place a call)", ["es"] = "Puede solicitar servicios de emergencia (se transmite como una solicitud — esta app no puede llamar por sí misma)", ["fr"] = "Peut demander les services d'urgence (transmis comme une demande — cette application ne peut pas passer d'appel elle-même)", ["de"] = "Darf Rettungsdienste anfordern (als Anfrage weitergeleitet — diese App kann selbst nicht anrufen)", ["pt"] = "Pode pedir serviços de emergência (transmitido como um pedido — esta aplicação não pode fazer chamadas)", ["it"] = "Può richiedere i servizi di emergenza (inoltrato come richiesta — questa app non può effettuare chiamate)", ["ja"] = "緊急サービスの要請を許可する（要請として転送されます。このアプリ自体は通報できません）", ["zh"] = "可以请求紧急服务（以请求的形式转达 — 本应用本身无法拨打电话）", ["hi"] = "आपातकालीन सेवाओं का अनुरोध कर सकता है (अनुरोध के रूप में भेजा जाता है — यह ऐप स्वयं कॉल नहीं कर सकता)", ["ar"] = "قد يطلب خدمات الطوارئ (يُنقل بوصفه طلبًا — لا يمكن لهذا التطبيق إجراء مكالمة بنفسه)" },
        ["tab.self"] = new() { ["en"] = "Me", ["es"] = "Yo", ["fr"] = "Moi", ["de"] = "Ich", ["pt"] = "Eu", ["it"] = "Io", ["ja"] = "わたし", ["zh"] = "我", ["hi"] = "मैं", ["ar"] = "أنا" },
        ["offline.title"] = new() { ["en"] = "What this deployment can reach", ["es"] = "Qué puede alcanzar esta instalación", ["fr"] = "Ce que ce déploiement peut atteindre", ["de"] = "Was diese Installation erreichen kann", ["pt"] = "O que esta instalação pode alcançar", ["it"] = "Cosa può raggiungere questa installazione", ["ja"] = "この環境が接続できる範囲", ["zh"] = "此部署可以连接到什么", ["hi"] = "यह परिनियोजन किस तक पहुँच सकता है", ["ar"] = "ما يمكن أن يصل إليه هذا النشر" },
        ["offline.on"] = new() { ["en"] = "Offline — nothing leaves this machine", ["es"] = "Sin conexión — nada sale de esta máquina", ["fr"] = "Hors ligne — rien ne quitte cette machine", ["de"] = "Offline — nichts verlässt diesen Rechner", ["pt"] = "Offline — nada sai desta máquina", ["it"] = "Offline — nulla esce da questa macchina", ["ja"] = "オフライン — このマシンから何も出ません", ["zh"] = "离线 — 任何内容都不会离开这台机器", ["hi"] = "ऑफ़लाइन — इस मशीन से कुछ भी बाहर नहीं जाता", ["ar"] = "دون اتصال — لا شيء يغادر هذا الجهاز" },
        ["offline.off"] = new() { ["en"] = "Online — this deployment can reach other machines", ["es"] = "En línea — esta instalación puede alcanzar otras máquinas", ["fr"] = "En ligne — ce déploiement peut atteindre d’autres machines", ["de"] = "Online — diese Installation kann andere Rechner erreichen", ["pt"] = "Online — esta instalação pode alcançar outras máquinas", ["it"] = "Online — questa installazione può raggiungere altre macchine", ["ja"] = "オンライン — この環境は他のマシンに接続できます", ["zh"] = "在线 — 此部署可以连接其他机器", ["hi"] = "ऑनलाइन — यह परिनियोजन अन्य मशीनों तक पहुँच सकता है", ["ar"] = "متصل — يمكن لهذا النشر الوصول إلى أجهزة أخرى" },
        ["self.profile_id"] = new() { ["en"] = "prf_…", ["es"] = "prf_…", ["fr"] = "prf_…", ["de"] = "prf_…", ["pt"] = "prf_…", ["it"] = "prf_…", ["ja"] = "prf_…", ["zh"] = "prf_…", ["hi"] = "prf_…", ["ar"] = "prf_…" },
        ["self.title"] = new() { ["en"] = "Your own profile", ["es"] = "Tu propio perfil", ["fr"] = "Votre propre profil", ["de"] = "Ihr eigenes Profil", ["pt"] = "O seu próprio perfil", ["it"] = "Il tuo profilo", ["ja"] = "あなた自身のプロフィール", ["zh"] = "你自己的档案", ["hi"] = "आपकी अपनी प्रोफ़ाइल", ["ar"] = "ملفك الشخصي" },
        ["self.lead"] = new() { ["en"] = "The QRME profile that speaks as you. The Guardian tells it nothing until you say which parts it may pass on, and you can see exactly what would go before any of it does.", ["es"] = "El perfil de QRME que habla como tú. El Guardián no le cuenta nada hasta que digas qué partes puede transmitir, y puedes ver exactamente qué se enviaría antes de que se envíe.", ["fr"] = "Le profil QRME qui parle en votre nom. Le Gardien ne lui dit rien tant que vous n’avez pas indiqué ce qu’il peut transmettre, et vous voyez exactement ce qui partirait avant que quoi que ce soit parte.", ["de"] = "Das QRME-Profil, das als Sie spricht. Der Guardian sagt ihm nichts, bis Sie festlegen, was er weitergeben darf, und Sie sehen genau, was ginge, bevor irgendetwas geht.", ["pt"] = "O perfil QRME que fala como você. O Guardião não lhe conta nada até dizer que partes pode transmitir, e vê exatamente o que iria antes de qualquer coisa ir.", ["it"] = "Il profilo QRME che parla come te. Il Guardian non gli dice nulla finché non indichi cosa può trasmettere, e vedi esattamente cosa partirebbe prima che parta.", ["ja"] = "あなたとして話す QRME のプロフィールです。どの部分を伝えてよいか決めるまで、ガーディアンは何も伝えません。送られる内容は送信前にそのまま確認できます。", ["zh"] = "以你的身份说话的 QRME 档案。在你指明可以转达哪些部分之前，守护者不会告诉它任何事，而且发送前你能看到确切会送出什么。", ["hi"] = "वह QRME प्रोफ़ाइल जो आपके रूप में बोलती है। जब तक आप यह न बताएँ कि कौन-से हिस्से भेजे जा सकते हैं, गार्जियन उसे कुछ नहीं बताता, और भेजे जाने से पहले आप ठीक-ठीक देख सकते हैं कि क्या जाएगा।", ["ar"] = "ملف QRME الذي يتحدث بصفتك. لا يخبره الحارس بشيء حتى تحدد ما يمكن نقله، ويمكنك أن ترى بالضبط ما سيُرسل قبل أن يُرسل أي شيء." },
        // Linking by signing in, rather than by pasting a `prf_…` id and an owner token nobody can find. The paste-it keys stay: still the right door for somebody who holds both.
        ["self.signin.title"] = new() { ["en"] = "Sign in to QRME", ["es"] = "Inicia sesión en QRME", ["fr"] = "Se connecter à QRME", ["de"] = "Bei QRME anmelden", ["pt"] = "Inicia sessão no QRME", ["it"] = "Accedi a QRME", ["ja"] = "QRME にサインイン", ["zh"] = "登录 QRME", ["hi"] = "QRME में साइन इन करें", ["ar"] = "تسجيل الدخول إلى QRME" },
        ["self.signin.pitch"] = new() { ["en"] = "Your QRME email and password. The Guardian finds your own profile and gets its key for you — neither the password nor anything else from the sign-in is kept.", ["es"] = "Tu correo y contraseña de QRME. El Guardián encuentra tu propio perfil y obtiene su clave por ti; ni la contraseña ni nada más del inicio de sesión se guarda.", ["fr"] = "Votre e-mail et mot de passe QRME. Le Gardien trouve votre propre profil et en obtient la clé pour vous — ni le mot de passe ni rien d'autre de la connexion n'est conservé.", ["de"] = "Deine QRME-E-Mail und dein Passwort. Der Guardian findet dein eigenes Profil und holt dessen Schlüssel für dich — weder das Passwort noch sonst etwas aus der Anmeldung wird behalten.", ["pt"] = "O teu email e palavra-passe do QRME. O Guardião encontra o teu próprio perfil e obtém a chave por ti — nem a palavra-passe nem mais nada do início de sessão fica guardado.", ["it"] = "La tua email e password QRME. Il Guardian trova il tuo profilo e ne ottiene la chiave per te — né la password né altro dell'accesso viene conservato.", ["ja"] = "QRME のメールアドレスとパスワードです。ガーディアンがあなた自身のプロフィールを見つけ、その鍵を取得します。パスワードもサインインの内容も保存されません。", ["zh"] = "你的 QRME 邮箱和密码。守护者会找到你自己的档案并替你取得它的钥匙——密码和登录过程中的任何东西都不会被保存。", ["hi"] = "आपका QRME ईमेल और पासवर्ड। गार्जियन आपकी अपनी प्रोफ़ाइल ढूँढ़कर उसकी कुंजी आपके लिए ले लेता है — न पासवर्ड रखा जाता है, न साइन-इन से और कुछ।", ["ar"] = "بريدك وكلمة مرورك في QRME. يجد الحارس ملفك الشخصي ويحصل على مفتاحه نيابةً عنك — ولا تُحفظ كلمة المرور ولا أي شيء آخر من تسجيل الدخول." },
        ["self.signin.email"] = new() { ["en"] = "QRME email", ["es"] = "Correo de QRME", ["fr"] = "E-mail QRME", ["de"] = "QRME-E-Mail", ["pt"] = "Email do QRME", ["it"] = "Email QRME", ["ja"] = "QRME のメールアドレス", ["zh"] = "QRME 邮箱", ["hi"] = "QRME ईमेल", ["ar"] = "بريد QRME" },
        ["self.signin.password"] = new() { ["en"] = "QRME password", ["es"] = "Contraseña de QRME", ["fr"] = "Mot de passe QRME", ["de"] = "QRME-Passwort", ["pt"] = "Palavra-passe do QRME", ["it"] = "Password QRME", ["ja"] = "QRME のパスワード", ["zh"] = "QRME 密码", ["hi"] = "QRME पासवर्ड", ["ar"] = "كلمة مرور QRME" },
        ["self.signin.button"] = new() { ["en"] = "Find my profile", ["es"] = "Buscar mi perfil", ["fr"] = "Trouver mon profil", ["de"] = "Mein Profil finden", ["pt"] = "Encontrar o meu perfil", ["it"] = "Trova il mio profilo", ["ja"] = "自分のプロフィールを探す", ["zh"] = "找到我的档案", ["hi"] = "मेरी प्रोफ़ाइल ढूँढ़ें", ["ar"] = "ابحث عن ملفي" },
        ["self.signin.choose"] = new() { ["en"] = "That account has more than one profile of you. Which one should the Guardian speak to?", ["es"] = "Esa cuenta tiene más de un perfil tuyo. ¿Con cuál debe hablar el Guardián?", ["fr"] = "Ce compte a plusieurs profils de vous. Auquel le Gardien doit-il parler ?", ["de"] = "Dieses Konto hat mehr als ein Profil von dir. Mit welchem soll der Guardian sprechen?", ["pt"] = "Essa conta tem mais do que um perfil teu. Com qual deve o Guardião falar?", ["it"] = "Quell'account ha più di un profilo di te. A quale deve parlare il Guardian?", ["ja"] = "そのアカウントにはあなた自身のプロフィールが複数あります。ガーディアンはどれに話しかけますか。", ["zh"] = "那个账户里有不止一个你自己的档案。守护者应该跟哪一个说话？", ["hi"] = "उस खाते में आपकी एक से अधिक प्रोफ़ाइल हैं। गार्जियन किससे बात करे?", ["ar"] = "يحتوي ذلك الحساب على أكثر من ملف شخصي لك. مع أيّها يتحدّث الحارس؟" },
        ["self.signin.paste_instead"] = new() { ["en"] = "Or paste an id and token", ["es"] = "O pega un id y un token", ["fr"] = "Ou coller un identifiant et un jeton", ["de"] = "Oder ID und Token einfügen", ["pt"] = "Ou cola um id e um token", ["it"] = "Oppure incolla id e token", ["ja"] = "または ID とトークンを貼り付ける", ["zh"] = "或者粘贴 id 和令牌", ["hi"] = "या id और टोकन चिपकाएँ", ["ar"] = "أو الصق معرِّفًا ورمزًا" },
        ["self.link"] = new() { ["en"] = "Link it", ["es"] = "Vincúlalo", ["fr"] = "Le relier", ["de"] = "Verknüpfen", ["pt"] = "Ligar", ["it"] = "Collegalo", ["ja"] = "リンクする", ["zh"] = "关联它", ["hi"] = "इसे जोड़ें", ["ar"] = "اربطه" },
        ["self.paste"] = new() { ["en"] = "Paste the profile's id and your owner token from QRME. It has to be a profile QRME calls your own — a made-up one will be refused.", ["es"] = "Pega el id del perfil y tu token de propietario de QRME. Tiene que ser un perfil que QRME considere tuyo; uno inventado será rechazado.", ["fr"] = "Collez l’identifiant du profil et votre jeton de propriétaire QRME. Ce doit être un profil que QRME reconnaît comme le vôtre ; un profil inventé sera refusé.", ["de"] = "Fügen Sie die Profil-ID und Ihr Eigentümer-Token aus QRME ein. Es muss ein Profil sein, das QRME als Ihr eigenes führt — ein erfundenes wird abgelehnt.", ["pt"] = "Cole o id do perfil e o seu token de proprietário do QRME. Tem de ser um perfil que o QRME considere seu — um inventado será recusado.", ["it"] = "Incolla l’id del profilo e il tuo token di proprietario da QRME. Deve essere un profilo che QRME riconosce come tuo — uno inventato verrà rifiutato.", ["ja"] = "QRME のプロフィール ID と所有者トークンを貼り付けてください。QRME があなた自身のものと認めるプロフィールに限られ、架空のものは拒否されます。", ["zh"] = "粘贴档案 id 和你在 QRME 的所有者令牌。必须是 QRME 认定属于你自己的档案 — 编造的会被拒绝。", ["hi"] = "QRME से प्रोफ़ाइल का id और अपना स्वामी टोकन चिपकाएँ। यह ऐसी प्रोफ़ाइल होनी चाहिए जिसे QRME आपकी अपनी मानता हो — बनावटी को अस्वीकार कर दिया जाएगा।", ["ar"] = "الصق معرِّف الملف ورمز المالك الخاص بك من QRME. يجب أن يكون ملفًا يعتبره QRME ملكك — وسيُرفض أي ملف مُختلق." },
        ["self.owner_token"] = new() { ["en"] = "owner token", ["es"] = "token de propietario", ["fr"] = "jeton de propriétaire", ["de"] = "Eigentümer-Token", ["pt"] = "token de proprietário", ["it"] = "token di proprietario", ["ja"] = "所有者トークン", ["zh"] = "所有者令牌", ["hi"] = "स्वामी टोकन", ["ar"] = "رمز المالك" },
        ["self.link_button"] = new() { ["en"] = "Link this profile", ["es"] = "Vincular este perfil", ["fr"] = "Relier ce profil", ["de"] = "Dieses Profil verknüpfen", ["pt"] = "Ligar este perfil", ["it"] = "Collega questo profilo", ["ja"] = "このプロフィールをリンク", ["zh"] = "关联此档案", ["hi"] = "इस प्रोफ़ाइल को जोड़ें", ["ar"] = "اربط هذا الملف" },
        ["self.may_know"] = new() { ["en"] = "What it may know", ["es"] = "Qué puede saber", ["fr"] = "Ce qu’il peut savoir", ["de"] = "Was es wissen darf", ["pt"] = "O que pode saber", ["it"] = "Cosa può sapere", ["ja"] = "伝えてよいこと", ["zh"] = "它可以知道什么", ["hi"] = "यह क्या जान सकता है", ["ar"] = "ما يمكن أن يعرفه" },
        ["self.until_tick"] = new() { ["en"] = "Nothing is passed on until you tick it.", ["es"] = "No se transmite nada hasta que lo marques.", ["fr"] = "Rien n’est transmis tant que vous ne l’avez pas coché.", ["de"] = "Nichts wird weitergegeben, bis Sie es ankreuzen.", ["pt"] = "Nada é transmitido até o marcar.", ["it"] = "Non viene trasmesso nulla finché non lo spunti.", ["ja"] = "チェックするまで何も伝えられません。", ["zh"] = "在你勾选之前，不会转达任何内容。", ["hi"] = "जब तक आप चुनें नहीं, कुछ भी नहीं भेजा जाता।", ["ar"] = "لا يُنقل شيء حتى تحدده." },
        ["self.exactly"] = new() { ["en"] = "Exactly what would be sent", ["es"] = "Exactamente lo que se enviaría", ["fr"] = "Exactement ce qui serait envoyé", ["de"] = "Genau das, was gesendet würde", ["pt"] = "Exatamente o que seria enviado", ["it"] = "Esattamente ciò che verrebbe inviato", ["ja"] = "送られる内容そのもの", ["zh"] = "确切会发送的内容", ["hi"] = "ठीक वही जो भेजा जाएगा", ["ar"] = "ما سيُرسل بالضبط" },
        ["self.nothing_ticked"] = new() { ["en"] = "Nothing, because nothing is ticked.", ["es"] = "Nada, porque no hay nada marcado.", ["fr"] = "Rien, parce que rien n’est coché.", ["de"] = "Nichts, weil nichts angekreuzt ist.", ["pt"] = "Nada, porque nada está marcado.", ["it"] = "Niente, perché non è spuntato nulla.", ["ja"] = "何もチェックされていないため、何もありません。", ["zh"] = "没有内容，因为没有勾选任何项。", ["hi"] = "कुछ नहीं, क्योंकि कुछ चुना नहीं गया है।", ["ar"] = "لا شيء، لأنه لم يتم تحديد أي شيء." },
        ["self.message_itself"] = new() { ["en"] = "This is the message itself, not a description of it. Medication is the one part made of your own words, so it shows the names as you typed them.", ["es"] = "Este es el mensaje en sí, no una descripción. La medicación es la única parte hecha con tus propias palabras, así que muestra los nombres tal como los escribiste.", ["fr"] = "Ceci est le message lui-même, pas sa description. Les médicaments sont la seule partie faite de vos propres mots : les noms s’affichent tels que vous les avez saisis.", ["de"] = "Dies ist die Nachricht selbst, keine Beschreibung. Die Medikation ist der einzige Teil aus Ihren eigenen Worten, daher erscheinen die Namen so, wie Sie sie eingegeben haben.", ["pt"] = "Esta é a mensagem em si, não uma descrição. A medicação é a única parte feita das suas próprias palavras, por isso mostra os nomes tal como os escreveu.", ["it"] = "Questo è il messaggio stesso, non una sua descrizione. I farmaci sono l’unica parte fatta di parole tue, quindi i nomi appaiono come li hai scritti.", ["ja"] = "これは説明ではなく、メッセージそのものです。薬だけはご自身の言葉でできているため、入力したとおりの名称が表示されます。", ["zh"] = "这就是消息本身，而不是对它的描述。用药是唯一由你自己的措辞构成的部分，因此名称按你输入的原样显示。", ["hi"] = "यह संदेश स्वयं है, उसका विवरण नहीं। दवा ही एकमात्र हिस्सा है जो आपके अपने शब्दों से बना है, इसलिए नाम वैसे ही दिखते हैं जैसे आपने लिखे।", ["ar"] = "هذه هي الرسالة نفسها، لا وصفٌ لها. الدواء هو الجزء الوحيد المكوَّن من كلماتك، لذا تظهر الأسماء كما كتبتها." },
        ["self.send"] = new() { ["en"] = "Send this to my profile", ["es"] = "Enviar esto a mi perfil", ["fr"] = "Envoyer ceci à mon profil", ["de"] = "Dies an mein Profil senden", ["pt"] = "Enviar isto ao meu perfil", ["it"] = "Invia questo al mio profilo", ["ja"] = "これを自分のプロフィールに送る", ["zh"] = "把这个发送到我的档案", ["hi"] = "इसे मेरी प्रोफ़ाइल को भेजें", ["ar"] = "أرسل هذا إلى ملفي" },
        ["self.stop"] = new() { ["en"] = "Stop", ["es"] = "Detener", ["fr"] = "Arrêter", ["de"] = "Beenden", ["pt"] = "Parar", ["it"] = "Ferma", ["ja"] = "やめる", ["zh"] = "停止", ["hi"] = "रोकें", ["ar"] = "إيقاف" },
        ["self.unlink_note"] = new() { ["en"] = "Unlinking removes the token and everything you ticked. What the profile was already told stays in its own source list, in QRME, where you can delete it.", ["es"] = "Desvincular elimina el token y todo lo que marcaste. Lo que ya se le dijo al perfil permanece en su propia lista de fuentes, en QRME, donde puedes borrarlo.", ["fr"] = "Le fait de délier supprime le jeton et tout ce que vous aviez coché. Ce qui a déjà été dit au profil reste dans sa liste de sources, dans QRME, où vous pouvez le supprimer.", ["de"] = "Das Trennen entfernt das Token und alles, was Sie angekreuzt hatten. Was dem Profil bereits mitgeteilt wurde, bleibt in dessen Quellenliste in QRME, wo Sie es löschen können.", ["pt"] = "Desligar remove o token e tudo o que marcou. O que já foi dito ao perfil fica na sua própria lista de fontes, no QRME, onde o pode apagar.", ["it"] = "Scollegare rimuove il token e tutto ciò che avevi spuntato. Quanto già detto al profilo resta nel suo elenco di fonti, in QRME, dove puoi eliminarlo.", ["ja"] = "リンクを解除するとトークンとチェックした内容がすべて削除されます。すでにプロフィールに伝えた内容は QRME のソース一覧に残り、そこで削除できます。", ["zh"] = "取消关联会移除令牌和你勾选的全部内容。已经告诉档案的内容仍留在 QRME 的来源列表中，你可以在那里删除。", ["hi"] = "अनलिंक करने से टोकन और आपके चुने हुए सब कुछ हट जाता है। प्रोफ़ाइल को पहले जो बताया जा चुका है वह QRME की उसकी स्रोत सूची में रहता है, जहाँ आप उसे मिटा सकते हैं।", ["ar"] = "يؤدي إلغاء الربط إلى إزالة الرمز وكل ما حددته. ويبقى ما قيل للملف سابقًا في قائمة مصادره داخل QRME، حيث يمكنك حذفه." },
        ["self.unlink"] = new() { ["en"] = "Unlink", ["es"] = "Desvincular", ["fr"] = "Dissocier", ["de"] = "Trennen", ["pt"] = "Desvincular", ["it"] = "Scollega", ["ja"] = "リンク解除", ["zh"] = "取消关联", ["hi"] = "अनलिंक करें", ["ar"] = "إلغاء الربط" },
        ["self.linked_note"] = new() { ["en"] = "Linked. Nothing is shared yet.", ["es"] = "Vinculado. Todavía no se comparte nada.", ["fr"] = "Relié. Rien n’est encore partagé.", ["de"] = "Verknüpft. Es wird noch nichts geteilt.", ["pt"] = "Ligado. Ainda não é partilhado nada.", ["it"] = "Collegato. Non è ancora condiviso nulla.", ["ja"] = "リンクしました。まだ何も共有されていません。", ["zh"] = "已关联。尚未共享任何内容。", ["hi"] = "जुड़ गया। अभी कुछ भी साझा नहीं किया गया।", ["ar"] = "تم الربط. لم تتم مشاركة أي شيء بعد." },
